package com.fasterxml.jackson.databind.introspect;

import java.util.List;

import com.fasterxml.jackson.databind.AnnotationIntrospector;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.cfg.MapperConfig;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class AnnotationIntrospectorPrimaryCreatorTest
{
    @Test
    void primaryCreatorFromSecondaryIntrospectorIsUsed() throws Exception
    {
        ObjectMapper mapper = new ObjectMapper();
        mapper.disable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES);

        PrimaryCreatorIntrospector secondary = new PrimaryCreatorIntrospector();
        mapper.setAnnotationIntrospector(AnnotationIntrospector.pair(
                new JacksonAnnotationIntrospector(), secondary));

        PrimaryCreatorBean value = mapper.readValue(
                "{\"id\":13,\"name\":\"Bob\"}", PrimaryCreatorBean.class);

        assertTrue(secondary.wasPrimaryCreatorInvoked(),
                "Expected AnnotationIntrospector.findPrimaryCreator() to be called");
        assertEquals(13, value.getId());
        assertEquals("Bob", value.getName());
    }

    static class PrimaryCreatorBean
    {
        private final int id;
        private final String name;

        public PrimaryCreatorBean() {
            this.id = -1;
            this.name = "default";
        }

        public PrimaryCreatorBean(int id, String name) {
            this.id = id;
            this.name = name;
        }

        public int getId() {
            return id;
        }

        public String getName() {
            return name;
        }
    }

    static class PrimaryCreatorIntrospector extends JacksonAnnotationIntrospector
    {
        private AnnotatedWithParams _primaryCreator;
        private boolean _primaryCreatorInvoked;

        @Override
        public PotentialCreator findPrimaryCreator(MapperConfig<?> config,
                AnnotatedClass valueClass,
                List<PotentialCreator> declaredConstructors,
                List<PotentialCreator> declaredFactories)
        {
            _primaryCreatorInvoked = true;
            for (PotentialCreator candidate : declaredConstructors) {
                if (candidate.paramCount() == 2) {
                    _primaryCreator = candidate.creator();
                    return candidate;
                }
            }
            return null;
        }

        @Override
        public String findImplicitPropertyName(AnnotatedMember member)
        {
            if ((_primaryCreator != null) && (member instanceof AnnotatedParameter)) {
                AnnotatedParameter param = (AnnotatedParameter) member;
                if (param.getOwner() == _primaryCreator) {
                    return (param.getIndex() == 0) ? "id" : "name";
                }
            }
            return super.findImplicitPropertyName(member);
        }

        public boolean wasPrimaryCreatorInvoked() {
            return _primaryCreatorInvoked;
        }
    }
}

