package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.annotation.JsonCreator;
import com.fasterxml.jackson.databind.AnnotationIntrospector;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;

import java.util.List;

/**
 * Tests for the new extension point AnnotationIntrospector.findPrimaryCreator()
 * integrated into POJOPropertiesCollector._addCreators, ensuring that:
 *  - A non-standard static factory method (which would normally be pruned as "non-factory")
 *    can be designated as the Primary Creator by a custom AnnotationIntrospector.
 *  - AnnotationIntrospectorPair delegates to the secondary introspector if the primary returns null.
 */
public class PrimaryCreatorExtensionPointTest {

    // Type under test: Not a Record; has a private ctor and a "weird" static factory method
    public static class NonRecordWithWeirdFactory {
        public final String v;

        private NonRecordWithWeirdFactory(String v) {
            this.v = v;
        }

        // Non-standard method name to ensure it does NOT "look like" a factory method
        public static NonRecordWithWeirdFactory buiLd(String value) {
            return new NonRecordWithWeirdFactory("FAC:" + value);
        }
    }

    // Introspector that does nothing special (returns null for primary)
    static class NullPrimaryIntrospector extends NopAnnotationIntrospector {
        private static final long serialVersionUID = 1L;

        @Override
        public PotentialCreator findPrimaryCreator(MapperConfig<?> config,
                                                   AnnotatedClass valueClass,
                                                   List<PotentialCreator> declaredConstructors,
                                                   List<PotentialCreator> declaredFactories) {
            return null;
        }
    }

    // Introspector that selects the "weird" static factory as the Primary Creator and marks it Delegating
    static class SelectWeirdFactoryAsPrimaryIntrospector extends NopAnnotationIntrospector {
        private static final long serialVersionUID = 1L;

        @Override
        public PotentialCreator findPrimaryCreator(MapperConfig<?> config,
                                                   AnnotatedClass valueClass,
                                                   List<PotentialCreator> declaredConstructors,
                                                   List<PotentialCreator> declaredFactories) {
            if (valueClass.getRawType() == NonRecordWithWeirdFactory.class) {
                for (PotentialCreator pc : declaredFactories) {
                    AnnotatedWithParams c = pc.creator();
                    if (c instanceof AnnotatedMethod) {
                        AnnotatedMethod m = (AnnotatedMethod) c;
                        if ("buiLd".equals(m.getName()) && m.getParameterCount() == 1) {
                            // Mark as delegating so JSON String input is accepted
                            return pc.overrideMode(JsonCreator.Mode.DELEGATING);
                        }
                    }
                }
            }
            return null;
        }
    }

    @Test
    public void testPrimaryDelegatingFactoryMethodIsUsed() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        // Use only the primary-selecting introspector
        mapper.setAnnotationIntrospector(new SelectWeirdFactoryAsPrimaryIntrospector());

        // Input is a JSON String; should be handled by delegating primary creator (static factory)
        NonRecordWithWeirdFactory result = mapper.readValue("\"abc\"", NonRecordWithWeirdFactory.class);
        Assertions.assertNotNull(result);
        Assertions.assertEquals("FAC:abc", result.v, "Primary delegating factory should be used for String input");
    }

    @Test
    public void testAnnotationIntrospectorPairDelegationForPrimaryCreator() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        // Pair: first returns null, second selects the primary
        AnnotationIntrospector ai = AnnotationIntrospector.pair(
                new NullPrimaryIntrospector(),
                new SelectWeirdFactoryAsPrimaryIntrospector()
        );
        mapper.setAnnotationIntrospector(ai);

        NonRecordWithWeirdFactory result = mapper.readValue("\"xyz\"", NonRecordWithWeirdFactory.class);
        Assertions.assertNotNull(result);
        // Should still be created via the weird static factory due to secondary introspector
        Assertions.assertEquals("FAC:xyz", result.v, "Secondary introspector in pair should provide Primary creator");
    }
}

