package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.annotation.JsonCreator;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.databind.AnnotationIntrospector;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.introspect.AnnotatedClass;
import com.fasterxml.jackson.databind.introspect.NopAnnotationIntrospector;
import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests for the new extension point AnnotationIntrospector.findPrimaryCreator()
 * and its integration within POJOPropertiesCollector:
 * - Ensures a non-annotated, non-standard-named factory method can be selected
 *   as the Primary Creator and used as properties-based creator.
 * - Ensures a non-annotated, non-standard-named single-arg factory can be
 *   selected as the Primary Creator and used as a delegating creator.
 */
public class FindPrimaryCreatorTest {

    /**
     * Custom Introspector to pick a specific factory method as "Primary Creator"
     * for our test classes. It selects:
     * - FactoryPropertiesPrimaryBean.makeMe(...) as a properties-based primary creator
     * - DelegatingPrimaryBean.make(String) as a delegating primary creator
     */
    static class PrimaryChoosingIntrospector extends NopAnnotationIntrospector {
        private static final long serialVersionUID = 1L;

        @Override
        public PotentialCreator findPrimaryCreator(com.fasterxml.jackson.databind.cfg.MapperConfig<?> config,
                                                   AnnotatedClass valueClass,
                                                   List<PotentialCreator> declaredConstructors,
                                                   List<PotentialCreator> declaredFactories) {
            final Class<?> raw = valueClass.getRawType();
            if (raw == FactoryPropertiesPrimaryBean.class) {
                // Choose the "makeMe" factory as primary (properties-based)
                for (PotentialCreator pc : declaredFactories) {
                    if (pc.creator() instanceof AnnotatedMethod) {
                        AnnotatedMethod am = (AnnotatedMethod) pc.creator();
                        if ("makeMe".equals(am.getName())) {
                            // Leave mode as DEFAULT => properties-based (since multi-arg, not delegating)
                            return pc;
                        }
                    }
                }
            } else if (raw == DelegatingPrimaryBean.class) {
                // Choose the "make" factory as primary (delegating)
                for (PotentialCreator pc : declaredFactories) {
                    if (pc.creator() instanceof AnnotatedMethod) {
                        AnnotatedMethod am = (AnnotatedMethod) pc.creator();
                        if ("make".equals(am.getName())) {
                            // Override mode to DELEGATING to trigger delegating-creator path
                            return pc.overrideMode(JsonCreator.Mode.DELEGATING);
                        }
                    }
                }
            }
            return null;
        }
    }

    // Bean with two non-standard-named factory methods using @JsonProperty for parameter names.
    public static class FactoryPropertiesPrimaryBean {
        private final int a;
        private final String b;
        private final String source;

        private FactoryPropertiesPrimaryBean(int a, String b, String source) {
            this.a = a;
            this.b = b;
            this.source = source;
        }

        // Primary should be this one, chosen by our introspector (non-standard name)
        public static FactoryPropertiesPrimaryBean makeMe(@JsonProperty("a") int a,
                                                          @JsonProperty("b") String b) {
            return new FactoryPropertiesPrimaryBean(a, b, "makeMe");
        }

        // Another non-standard factory that should be ignored after removal of non-factories
        public static FactoryPropertiesPrimaryBean alsoMake(@JsonProperty("a") int a,
                                                            @JsonProperty("b") String b) {
            return new FactoryPropertiesPrimaryBean(a, b, "alsoMake");
        }

        public int getA() { return a; }
        public String getB() { return b; }
        public String getSource() { return source; }
    }

    // Bean with a single-arg non-standard factory, to be used as a delegating creator.
    public static class DelegatingPrimaryBean {
        private final String v;

        private DelegatingPrimaryBean(String v) {
            this.v = v;
        }

        public static DelegatingPrimaryBean make(String v) {
            return new DelegatingPrimaryBean(v);
        }

        public String getV() { return v; }
    }

    private ObjectMapper mapperWithPrimaryChoosingAI() {
        ObjectMapper m = new ObjectMapper();
        // Pair default Jackson introspector (to honor @JsonProperty) with our custom chooser
        AnnotationIntrospector ai = AnnotationIntrospector.pair(
                new com.fasterxml.jackson.databind.introspect.JacksonAnnotationIntrospector(),
                new PrimaryChoosingIntrospector()
        );
        m.setAnnotationIntrospector(ai);
        return m;
    }

    @Test
    public void testPrimaryFactoryPropertiesBasedIsUsed() throws Exception {
        ObjectMapper mapper = mapperWithPrimaryChoosingAI();

        String json = "{\"a\":7,\"b\":\"xyz\"}";
        FactoryPropertiesPrimaryBean result = mapper.readValue(json, FactoryPropertiesPrimaryBean.class);

        assertNotNull(result, "Deserialization result should not be null");
        assertEquals(7, result.getA(), "Field 'a' should be populated via primary properties-based factory");
        assertEquals("xyz", result.getB(), "Field 'b' should be populated via primary properties-based factory");
        // Ensure the specifically chosen primary factory was used
        assertEquals("makeMe", result.getSource(),
                "Primary factory method 'makeMe' should be used when marked as Primary Creator");
    }

    @Test
    public void testPrimaryFactoryDelegatingIsUsed() throws Exception {
        ObjectMapper mapper = mapperWithPrimaryChoosingAI();

        String json = "\"hello-world\"";
        DelegatingPrimaryBean result = mapper.readValue(json, DelegatingPrimaryBean.class);

        assertNotNull(result, "Deserialization result should not be null");
        assertEquals("hello-world", result.getV(),
                "Delegating primary factory method should receive the raw value from JSON string");
    }
}

