package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.annotation.JsonCreator;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.databind.AnnotationIntrospector;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;

public class PrimaryCreatorExtensionTest {

    // Custom AnnotationIntrospector that selects a "Primary" creator for our test classes
    static class PrimaryChoosingIntrospector extends NopAnnotationIntrospector {
        private static final long serialVersionUID = 1L;

        @Override
        public PotentialCreator findPrimaryCreator(MapperConfig<?> config,
                                                   AnnotatedClass valueClass,
                                                   List<PotentialCreator> declaredConstructors,
                                                   List<PotentialCreator> declaredFactories) {
            Class<?> raw = valueClass.getRawType();

            // For BeanProps: choose 2-arg properties-based constructor
            if (raw == BeanProps.class) {
                for (PotentialCreator pc : declaredConstructors) {
                    if (pc.paramCount() == 2) {
                        // Mark as PROPERTIES to be explicit
                        return pc.overrideMode(JsonCreator.Mode.PROPERTIES);
                    }
                }
            }

            // For BeanFromScalar: choose 1-arg factory and mark as delegating
            if (raw == BeanFromScalar.class) {
                for (PotentialCreator pc : declaredFactories) {
                    if (pc.paramCount() == 1) {
                        // Mark this factory as DELEGATING so scalar value can bind directly
                        return pc.overrideMode(JsonCreator.Mode.DELEGATING);
                    }
                }
            }
            return null;
        }
    }

    // Bean with multiple constructors and no @JsonCreator on the constructors:
    // We rely on PrimaryChoosingIntrospector to select the 2-arg constructor as Primary.
    public static class BeanProps {
        public final int a;
        public final String b;
        public final String constructedBy;

        public BeanProps(@JsonProperty("a") int a, @JsonProperty("b") String b) {
            this.a = a;
            this.b = b;
            this.constructedBy = "ctor(a,b)";
        }

        // Additional constructor present to ensure there is more than one option
        public BeanProps(String onlyB) {
            this.a = -1;
            this.b = onlyB;
            this.constructedBy = "ctor(b)";
        }
    }

    // Bean created via a static factory without @JsonCreator:
    // PrimaryChoosingIntrospector will mark the factory as DELEGATING.
    public static class BeanFromScalar {
        public final String value;
        public final String constructedBy;

        private BeanFromScalar(String v, String source) {
            this.value = v;
            this.constructedBy = source;
        }

        // Non-annotated static factory; our introspector will choose this as primary delegating
        public static BeanFromScalar create(String v) {
            return new BeanFromScalar(v, "factory:create(String)");
        }
    }

    private ObjectMapper mapperWithPrimaryChoosingAI() {
        ObjectMapper mapper = new ObjectMapper();
        AnnotationIntrospector custom = new PrimaryChoosingIntrospector();
        // Pair our custom introspector with Jackson's default to retain standard annotation processing
        AnnotationIntrospector defaultAI = new JacksonAnnotationIntrospector();
        mapper.setAnnotationIntrospector(new AnnotationIntrospectorPair(custom, defaultAI));
        return mapper;
    }

    @Test
    public void testPrimaryCreatorConstructorSelected() throws Exception {
        ObjectMapper mapper = mapperWithPrimaryChoosingAI();

        String json = "{\"a\":13,\"b\":\"xyz\"}";
        BeanProps result = mapper.readValue(json, BeanProps.class);

        assertEquals(13, result.a);
        assertEquals("xyz", result.b);
        // Verify that properties-based constructor was used
        assertEquals("ctor(a,b)", result.constructedBy);
    }

    @Test
    public void testPrimaryCreatorDelegatingFactorySelected() throws Exception {
        ObjectMapper mapper = mapperWithPrimaryChoosingAI();

        // Since our PrimaryChoosingIntrospector marks the factory as delegating,
        // we can deserialize directly from a JSON String
        String json = "\"hello\"";
        BeanFromScalar result = mapper.readValue(json, BeanFromScalar.class);

        assertEquals("hello", result.value);
        // Ensure the factory was used (and not any constructor)
        assertEquals("factory:create(String)", result.constructedBy);
    }
}

