package com.fasterxml.jackson.databind.introspect;

import java.util.List;
import java.util.Map;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

import com.fasterxml.jackson.databind.AnnotationIntrospector;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.PropertyName;
import com.fasterxml.jackson.databind.annotation.NoClass;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.introspect.AnnotatedClass;
import com.fasterxml.jackson.databind.introspect.NopAnnotationIntrospector;
import com.fasterxml.jackson.annotation.JsonCreator;

/**
 * Tests for the new AnnotationIntrospector.findPrimaryCreator() extension point and
 * related handling in POJOPropertiesCollector, as well as PotentialCreator implicitName().
 *
 * These tests:
 * - Provide a custom AnnotationIntrospector that selects a "primary" creator for specific classes
 *   without any explicit @JsonCreator annotation.
 * - Verify that the selected creator is used for deserialization.
 * - Verify that a non-standard static factory method (not normally recognized as a factory)
 *   is retained when it is designated as the primary creator.
 * - Exercise PotentialCreator.implicitName(int) via introspection; for a delegating one-arg Map
 *   parameter the implicit name should be null.
 */
public class PrimaryCreatorExtensionTest {

    // Bean with a single delegating constructor that accepts a Map; no @JsonCreator
    public static class MapDelegatingCtorBean {
        private final Map<String, Object> props;

        public MapDelegatingCtorBean(Map<String, Object> props) {
            this.props = props;
        }

        public Map<String, Object> getProps() {
            return props;
        }
    }

    // Bean with a single delegating static factory method that accepts a Map; method name is not a standard factory name
    public static class MapDelegatingFactoryBean {
        private final Map<String, Object> props;

        private MapDelegatingFactoryBean(Map<String, Object> props) {
            this.props = props;
        }

        // Intentionally non-standard name ("mapBuild") so it would normally be removed as non-factory;
        // it should be kept because introspector selects it as the primary creator.
        public static MapDelegatingFactoryBean mapBuild(Map<String, Object> props) {
            return new MapDelegatingFactoryBean(props);
        }

        public Map<String, Object> getProps() {
            return props;
        }
    }

    // Custom introspector that designates a "primary" creator for the two test classes above.
    // It also captures the last selected PotentialCreator for assertions.
    static class PrimarySelectingIntrospector extends NopAnnotationIntrospector {
        private static final long serialVersionUID = 1L;

        PotentialCreator lastPrimary;

        @Override
        public PotentialCreator findPrimaryCreator(MapperConfig<?> config,
                AnnotatedClass valueClass,
                List<PotentialCreator> declaredConstructors,
                List<PotentialCreator> declaredFactories) {

            Class<?> raw = valueClass.getAnnotated();
            if (raw == MapDelegatingCtorBean.class) {
                for (PotentialCreator pc : declaredConstructors) {
                    if (pc.paramCount() == 1 && Map.class.isAssignableFrom(pc.param(0).getRawType())) {
                        // Mark as delegating to ensure delegating handling path
                        pc.overrideMode(JsonCreator.Mode.DELEGATING);
                        // Introspect parameter names so implicit names array gets initialized
                        pc.introspectParamNames(config);
                        lastPrimary = pc;
                        return pc;
                    }
                }
            } else if (raw == MapDelegatingFactoryBean.class) {
                for (PotentialCreator pc : declaredFactories) {
                    if (pc.paramCount() == 1
                            && Map.class.isAssignableFrom(pc.param(0).getRawType())
                            && "mapBuild".equals(pc.creator().getName())) {
                        pc.overrideMode(JsonCreator.Mode.DELEGATING);
                        pc.introspectParamNames(config);
                        lastPrimary = pc;
                        return pc;
                    }
                }
            }
            return null;
        }
    }

    private ObjectMapper mapperWithPrimarySelectingIntrospector(PrimarySelectingIntrospector custom) {
        ObjectMapper m = new ObjectMapper();
        // Pair default introspector with our custom one; our custom will be consulted via AnnotationIntrospectorPair
        AnnotationIntrospector paired = AnnotationIntrospector.pair(new JacksonAnnotationIntrospector(), custom);
        m.setAnnotationIntrospector(paired);
        return m;
    }

    @Test
    public void testPrimaryDelegatingConstructorSelectedAndUsed() throws Exception {
        PrimarySelectingIntrospector custom = new PrimarySelectingIntrospector();
        ObjectMapper mapper = mapperWithPrimarySelectingIntrospector(custom);

        String json = "{\"x\":1,\"y\":\"a\"}";
        MapDelegatingCtorBean bean = mapper.readValue(json, MapDelegatingCtorBean.class);

        assertNotNull(bean);
        assertNotNull(bean.getProps());
        assertEquals(2, bean.getProps().size());
        assertEquals(1, ((Number) bean.getProps().get("x")).intValue());
        assertEquals("a", bean.getProps().get("y"));

        // Verify that our introspector was invoked and a primary creator was chosen
        assertNotNull(custom.lastPrimary, "Primary creator should have been selected");
        assertEquals(1, custom.lastPrimary.paramCount());
        // Mode should be DELEGATING as we overrode it
        assertEquals(JsonCreator.Mode.DELEGATING, custom.lastPrimary.creatorModeOrDefault());

        // Ensure implicit names were introspected and for a delegating Map parameter we get null
        PropertyName implicit0 = custom.lastPrimary.implicitName(0);
        assertNull(implicit0, "Implicit name for delegating Map parameter should be null");
    }

    @Test
    public void testPrimaryDelegatingFactoryRetainedAndUsed() throws Exception {
        PrimarySelectingIntrospector custom = new PrimarySelectingIntrospector();
        ObjectMapper mapper = mapperWithPrimarySelectingIntrospector(custom);

        String json = "{\"k1\":true,\"k2\":2}";
        MapDelegatingFactoryBean bean = mapper.readValue(json, MapDelegatingFactoryBean.class);

        assertNotNull(bean);
        assertNotNull(bean.getProps());
        assertEquals(2, bean.getProps().size());
        assertEquals(Boolean.TRUE, bean.getProps().get("k1"));
        assertEquals(2, ((Number) bean.getProps().get("k2")).intValue());

        // Verify primary was the factory method and it was not removed as a non-factory method
        assertNotNull(custom.lastPrimary, "Primary factory method should have been selected");
        assertEquals("mapBuild", custom.lastPrimary.creator().getName());
        assertEquals(JsonCreator.Mode.DELEGATING, custom.lastPrimary.creatorModeOrDefault());

        // For delegating Map parameter, implicit name remains null
        assertNull(custom.lastPrimary.implicitName(0));
    }
}

