        public static PropsBean oddFactory(@JsonProperty("a") int a,
                                           @JsonProperty("b") String b) {
            return new PropsBean(a, b);
        }

        public int getA() { return a; }
        public String getB() { return b; }
    }

    static class DelegatingBean {
        public final String value;

        private DelegatingBean(String v) { this.value = v; }

        // Non-standard factory name with single argument
        public static DelegatingBean makeFrom(String v) {
            return new DelegatingBean(v);
        }

        public String getValue() { return value; }
    }

    static class PrimaryCreatorIntrospector extends com.fasterxml.jackson.databind.introspect.JacksonAnnotationIntrospector {
        private static final long serialVersionUID = 1L;

        private final Class<?> targetType;
        private final JsonCreator.Mode modeToReturn;

        String capturedToString;

        PrimaryCreatorIntrospector(Class<?> targetType, JsonCreator.Mode modeToReturn) {
            this.targetType = targetType;
            this.modeToReturn = modeToReturn;
        }

        @Override
        public PotentialCreator findPrimaryCreator(MapperConfig<?> config,
                                                   AnnotatedClass valueClass,
                                                   List<PotentialCreator> declaredConstructors,
                                                   List<PotentialCreator> declaredFactories) {
            // Only act on the specific target type
            if (!valueClass.getRawType().equals(targetType)) {
                return null;
            }
            PotentialCreator chosen = null;
            if (!declaredFactories.isEmpty()) {
                // Prefer the first discovered factory method
                chosen = declaredFactories.get(0);
            } else if (!declaredConstructors.isEmpty()) {
                // Fallback: constructor (not used in these tests, but provided for completeness)
                chosen = declaredConstructors.get(0);
            }
            if (chosen != null) {
                // Ensure mode is explicitly set so delegating vs properties is honored
                chosen.overrideMode(modeToReturn);
                // Capture toString to validate PotentialCreator.toString() formatting and mode display
                capturedToString = chosen.toString();
