        Assertions.assertEquals("foo", bean.getB(), "Property 'b' should be set via primary factory");

        // Validate PotentialCreator.toString() reflects the overridden mode and includes class info
        Assertions.assertNotNull(introspector.capturedToString, "Introspector should have captured PotentialCreator.toString()");
        Assertions.assertTrue(introspector.capturedToString.contains("(mode=PROPERTIES)"),
                "PotentialCreator.toString() should include '(mode=PROPERTIES)': " + introspector.capturedToString);
        Assertions.assertTrue(introspector.capturedToString.contains("PropsBean"),
                "PotentialCreator.toString() should include the target class name: " + introspector.capturedToString);
    }

