package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.JavaType;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests to verify that TypeFactory recognizes java.lang.Iterable as an IterationType,
 * both for raw and parameterized usages, as per [databind#4443].
 */
public class TypeFactoryIterableTypeTest {

    @Test
    public void iterableRawRecognizedAsIterationType() {
        TypeFactory tf = TypeFactory.defaultInstance();

        JavaType t = tf.constructType(Iterable.class);

        assertNotNull(t, "Constructed JavaType for Iterable should not be null");
        assertTrue(t instanceof IterationType, "Iterable should be resolved as IterationType");
        assertEquals(Iterable.class, t.getRawClass(), "Raw class should be Iterable");

        JavaType contentType = t.getContentType();
        assertNotNull(contentType, "Content type for raw Iterable should not be null");
        // For raw/unenforced generics, content type should default to Object
        assertEquals(Object.class, contentType.getRawClass(), "Content type for raw Iterable should default to Object");
    }

    @Test
    public void iterableWithGenericParameterRecognizedAsIterationType() {
        TypeFactory tf = TypeFactory.defaultInstance();

        JavaType t = tf.constructType(new TypeReference<Iterable<String>>() {}.getType());

        assertNotNull(t, "Constructed JavaType for Iterable<String> should not be null");
        assertTrue(t instanceof IterationType, "Iterable<String> should be resolved as IterationType");
        assertEquals(Iterable.class, t.getRawClass(), "Raw class should be Iterable");

        JavaType contentType = t.getContentType();
        assertNotNull(contentType, "Content type for Iterable<String> should not be null");
        assertEquals(String.class, contentType.getRawClass(), "Content type for Iterable<String> should be String");
    }
}

