package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.exc.InvalidFormatException;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

public class ReadUnknownEnumAsNullOverrideTest {

    enum Color {
        RED, BLUE
    }

    static class PlainBean {
        public Color color;
    }

    static class AnnotatedWithoutBean {
        @JsonFormat(without = JsonFormat.Feature.READ_UNKNOWN_ENUM_VALUES_AS_NULL)
        public Color color;
    }

    static class AnnotatedWithBean {
        @JsonFormat(with = JsonFormat.Feature.READ_UNKNOWN_ENUM_VALUES_AS_NULL)
        public Color color;
    }

    @Test
    public void testGlobalFeatureAppliesWithoutAnnotation() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_AS_NULL);

        String json = "{\"color\":\"WHITE\"}";

        PlainBean bean = mapper.readValue(json, PlainBean.class);
        assertNull(bean.color, "Without per-field override, unknown enum should deserialize as null when global feature is enabled");
    }

    @Test
    public void testFieldLevelWithoutOverridesGlobalFeature() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        // Enable the global feature that would normally turn unknown enum values into nulls
        mapper.enable(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_AS_NULL);

        String json = "{\"color\":\"WHITE\"}";

        // With the per-field override disabling READ_UNKNOWN_ENUM_VALUES_AS_NULL,
        // deserialization should fail with InvalidFormatException for unknown enum value.
        InvalidFormatException ex = assertThrows(InvalidFormatException.class,
                () -> mapper.readValue(json, AnnotatedWithoutBean.class),
                "Per-field @JsonFormat(without=READ_UNKNOWN_ENUM_VALUES_AS_NULL) should override global feature and cause exception");
        assertTrue(ex.getMessage().contains("Color"), "Exception message should mention the target enum type");
    }

    @Test
    public void testFieldLevelWithEnablesWhenGlobalDisabled() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        // Global feature is disabled by default

        String json = "{\"color\":\"WHITE\"}";

        // With the per-field override enabling READ_UNKNOWN_ENUM_VALUES_AS_NULL,
        // deserialization should yield null for the unknown enum value.
        AnnotatedWithBean bean = mapper.readValue(json, AnnotatedWithBean.class);
        assertNull(bean.color, "Per-field @JsonFormat(with=READ_UNKNOWN_ENUM_VALUES_AS_NULL) should allow null for unknown enum even when global feature is disabled");

        // Control: without per-field override and with global disabled, it should throw
        assertThrows(InvalidFormatException.class,
                () -> mapper.readValue(json, PlainBean.class),
                "Without global or per-field enabling, unknown enum value should cause exception");
    }
}

