import com.fasterxml.jackson.annotation.Nulls;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;

import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.*;

public class NullsSkipOnBufferedPropertiesTest {

    // Simple leaf type to use within lists
    static class Inner {
        public String value;
    }

    // FIELD-BASED property: list1 is a field with default initialization and @JsonSetter(nulls = SKIP)
    static class MiddleFieldBased {
        public final String field1;

        @JsonSetter(nulls = Nulls.SKIP)
        public List<Inner> list1 = new ArrayList<>();

        @JsonCreator
        public MiddleFieldBased(@JsonProperty("field1") String field1) {
            this.field1 = field1;
        }

        public List<Inner> getList1() {
            return list1;
        }
    }

    static class OuterFieldBased {
        public List<MiddleFieldBased> list1;

        public List<MiddleFieldBased> getList1() {
            return list1;
        }
    }

    // METHOD-BASED property: list1 is set via a setter annotated with @JsonSetter(nulls = SKIP)
    static class MiddleMethodBased {
        public final String field1;

        private List<Inner> list1 = new ArrayList<>();

        @JsonCreator
        public MiddleMethodBased(@JsonProperty("field1") String field1) {
            this.field1 = field1;
        }

        public List<Inner> getList1() {
            return list1;
        }

        @JsonSetter(value = "list1", nulls = Nulls.SKIP)
        public void setList1(List<Inner> list1) {
            this.list1 = list1;
        }
    }

    static class OuterMethodBased {
        public List<MiddleMethodBased> list1;

        public List<MiddleMethodBased> getList1() {
            return list1;
        }
    }

    @Test
    public void testSkipNullForFieldPropertyBuffered() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // "list1" (of Middle) appears before "field1" so it's buffered; with Nulls.SKIP it must not override initializer
        String json = "{ \"list1\": [ { \"list1\": null, \"field1\": \"data\" } ] }";

        OuterFieldBased outer = mapper.readValue(json, OuterFieldBased.class);
        assertNotNull(outer);
        assertNotNull(outer.list1);
        assertEquals(1, outer.list1.size());

        MiddleFieldBased middle = outer.list1.get(0);
        assertNotNull(middle);
        assertEquals("data", middle.field1);

        // The critical assertion: null should be skipped, preserving the initialized ArrayList instance
        assertNotNull("list1 should not be null due to @JsonSetter(nulls = SKIP)", middle.getList1());
        assertTrue("list1 should remain the initialized empty list", middle.getList1().isEmpty());
    }

    @Test
    public void testSkipNullForMethodPropertyBuffered() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

