package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.core.Version;
import com.fasterxml.jackson.databind.AnnotationIntrospector;
import com.fasterxml.jackson.databind.MapperFeature;
import com.fasterxml.jackson.databind.PropertyName;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests for PropertyName.merge(...) and its integration via AnnotationIntrospectorPair.
 * These tests validate that:
 * - merge() combines simple name and namespace from two PropertyName instances with precedence.
 * - AnnotationIntrospectorPair delegates to PropertyName.merge(...) for various name lookups.
 * - For findRenameByField(...) secondary introspector has precedence as per original logic.
 */
public class AnnotationIntrospectorPairMergeTest {

    /**
     * Simple stub introspector that returns predefined PropertyName instances for different queries.
     * It ignores the Annotated/MapperConfig parameters.
     */
    static class StubIntrospector extends AnnotationIntrospector {
        private final PropertyName nameForSer;
        private final PropertyName nameForDeser;
        private final PropertyName wrapperName;
        private final PropertyName rootName;
        private final PropertyName renameByField;

        StubIntrospector(PropertyName nameForSer,
                         PropertyName nameForDeser,
                         PropertyName wrapperName,
                         PropertyName rootName,
                         PropertyName renameByField) {
            this.nameForSer = nameForSer;
            this.nameForDeser = nameForDeser;
            this.wrapperName = wrapperName;
            this.rootName = rootName;
            this.renameByField = renameByField;
        }

        @Override
        public Version version() {
            return Version.unknownVersion();
        }

        @Override
        public PropertyName findNameForSerialization(Annotated a) {
            return nameForSer;
        }

        @Override
        public PropertyName findNameForDeserialization(Annotated a) {
            return nameForDeser;
        }

        @Override
        public PropertyName findWrapperName(Annotated ann) {
            return wrapperName;
        }

        @Override
        public PropertyName findRootName(AnnotatedClass ac) {
            return rootName;
        }

        @Override
        public PropertyName findRenameByField(MapperConfig<?> config, AnnotatedField f, PropertyName implName) {
            return renameByField;
        }
    }

    @Test
    public void testPropertyNameMerge_NullsAndIdentity() {
        // null handling
        assertNull(PropertyName.merge(null, null));

        PropertyName pn = PropertyName.construct("foo", "ns1");
        assertSame(pn, PropertyName.merge(pn, null));
        assertSame(pn, PropertyName.merge(null, pn));

        // If second has empty simple and namespace, merge should return the first object as-is (identity)
        PropertyName emptyBoth = PropertyName.construct("", "");
        PropertyName merged = PropertyName.merge(pn, emptyBoth);
        assertSame(pn, merged);
        assertEquals("foo", merged.getSimpleName());
        assertEquals("ns1", merged.getNamespace());
    }

    @Test
    public void testPropertyNameMerge_CombinesPartsFromBoth() {
        // Primary has simple name only, Secondary has namespace only
        PropertyName primary = PropertyName.construct("a", "");
        PropertyName secondary = PropertyName.construct("", "urn:ns");
        PropertyName merged = PropertyName.merge(primary, secondary);

        assertEquals("a", merged.getSimpleName());
        assertEquals("urn:ns", merged.getNamespace());
        // Should be a new instance since it's a hybrid of both
        assertNotSame(primary, merged);
        assertNotSame(secondary, merged);
    }

    @Test
    public void testPairFindNameForSerialization_PrimaryUseDefaultSecondaryExplicit() {
        PropertyName secondaryValue = PropertyName.construct("prop", "urn:ns");

        AnnotationIntrospector primary = new StubIntrospector(
                PropertyName.USE_DEFAULT, // primary indicates no explicit rename
                null, null, null, null
        );
        AnnotationIntrospector secondary = new StubIntrospector(
                secondaryValue,
                null, null, null, null
        );
        AnnotationIntrospector pair = AnnotationIntrospector.pair(primary, secondary);

        PropertyName result = pair.findNameForSerialization(null);
        // With primary "use default" and secondary explicit, merged should be exactly the secondary instance
        assertSame(secondaryValue, result);
        assertEquals("prop", result.getSimpleName());
        assertEquals("urn:ns", result.getNamespace());
    }

    @Test
    public void testPairFindNameForSerialization_CombinePartsFromBoth() {
        // Primary provides simple name; Secondary provides namespace
        AnnotationIntrospector primary = new StubIntrospector(
                PropertyName.construct("prop", null),
                null, null, null, null
        );
        AnnotationIntrospector secondary = new StubIntrospector(
                PropertyName.construct("", "urn:ns"),
                null, null, null, null
        );
        AnnotationIntrospector pair = AnnotationIntrospector.pair(primary, secondary);

        PropertyName result = pair.findNameForSerialization(null);
        assertEquals("prop", result.getSimpleName());
        assertEquals("urn:ns", result.getNamespace());
    }

    @Test
    public void testPairFindWrapperName_CombinePartsFromBoth() {
        // Primary has namespace only (empty local), secondary has local only (empty namespace)
        AnnotationIntrospector primary = new StubIntrospector(
                null, null,
                PropertyName.construct("", "ns1"),
                null, null
        );
        AnnotationIntrospector secondary = new StubIntrospector(
                null, null,
                PropertyName.construct("wrap", ""),
                null, null
        );
        AnnotationIntrospector pair = AnnotationIntrospector.pair(primary, secondary);

        PropertyName result = pair.findWrapperName(null);
        assertEquals("wrap", result.getSimpleName());
        assertEquals("ns1", result.getNamespace());
    }

    @Test
    public void testPairFindRootName_CombinePartsFromBoth() {
        // Primary has namespace only; Secondary has simple only
        AnnotationIntrospector primary = new StubIntrospector(
                null, null, null,
                PropertyName.construct("", "ns-root"),
                null
        );
        AnnotationIntrospector secondary = new StubIntrospector(
                null, null, null,
                PropertyName.construct("root", ""),
                null
        );
        AnnotationIntrospector pair = AnnotationIntrospector.pair(primary, secondary);

        PropertyName result = pair.findRootName((AnnotatedClass) null);
        assertEquals("root", result.getSimpleName());
        assertEquals("ns-root", result.getNamespace());
    }

    @Test
    public void testPairFindRenameByField_SecondaryHasPrecedence_BothExplicit() {
        // As per original logic, secondary has precedence for rename-by-field
        AnnotationIntrospector primary = new StubIntrospector(
                null, null, null, null,
                PropertyName.construct("prim", "nsP")
        );
        AnnotationIntrospector secondary = new StubIntrospector(
                null, null, null, null,
                PropertyName.construct("sec", "nsS")
        );
        AnnotationIntrospector pair = AnnotationIntrospector.pair(primary, secondary);

        PropertyName result = pair.findRenameByField((MapperConfig<?>) null, (AnnotatedField) null, null);
        assertEquals("sec", result.getSimpleName());
        assertEquals("nsS", result.getNamespace());
    }

    @Test
    public void testPairFindRenameByField_SecondaryAndPrimaryCombined() {
        // Secondary provides namespace only; Primary provides simple only => merge(second, primary)
        AnnotationIntrospector primary = new StubIntrospector(
                null, null, null, null,
                PropertyName.construct("prim", "")
        );
        AnnotationIntrospector secondary = new StubIntrospector(
                null, null, null, null,
                PropertyName.construct("", "nsS")
        );
        AnnotationIntrospector pair = AnnotationIntrospector.pair(primary, secondary);

        PropertyName result = pair.findRenameByField((MapperConfig<?>) null, (AnnotatedField) null, null);
        assertEquals("prim", result.getSimpleName());
        assertEquals("nsS", result.getNamespace());
    }

    @Test
    public void testPairFindNameForDeserialization_PrimaryUseDefaultSecondaryExplicit() {
        PropertyName secondaryValue = PropertyName.construct("propD", "urn:deser");

        AnnotationIntrospector primary = new StubIntrospector(
                null,
                PropertyName.USE_DEFAULT,
                null, null, null
        );
        AnnotationIntrospector secondary = new StubIntrospector(
                null,
                secondaryValue,
                null, null, null
        );
        AnnotationIntrospector pair = AnnotationIntrospector.pair(primary, secondary);

        PropertyName result = pair.findNameForDeserialization(null);
        assertSame(secondaryValue, result);
        assertEquals("propD", result.getSimpleName());
        assertEquals("urn:deser", result.getNamespace());
    }
}

