package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.introspect.Annotated;
import com.fasterxml.jackson.databind.introspect.AnnotatedClass;
import com.fasterxml.jackson.databind.introspect.AnnotatedField;
import com.fasterxml.jackson.databind.introspect.AnnotationIntrospectorPair;
import com.fasterxml.jackson.databind.introspect.NopAnnotationIntrospector;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

public class PropertyNameMergeAndAnnotationIntrospectorPairTest {

    // Helper AnnotationIntrospector that returns fixed PropertyName values
    static class FixedNamesIntrospector extends NopAnnotationIntrospector {
        private final PropertyName forSer;
        private final PropertyName forDeser;
        private final PropertyName wrapper;
        private final PropertyName root;
        private final PropertyName renameByField;

        FixedNamesIntrospector(PropertyName forSer,
                               PropertyName forDeser,
                               PropertyName wrapper,
                               PropertyName root,
                               PropertyName renameByField) {
            this.forSer = forSer;
            this.forDeser = forDeser;
            this.wrapper = wrapper;
            this.root = root;
            this.renameByField = renameByField;
        }

        @Override
        public PropertyName findNameForSerialization(Annotated a) {
            return forSer;
        }

        @Override
        public PropertyName findNameForDeserialization(Annotated a) {
            return forDeser;
        }

        @Override
        public PropertyName findWrapperName(Annotated ann) {
            return wrapper;
        }

        @Override
        public PropertyName findRootName(AnnotatedClass ac) {
            return root;
        }

        @Override
        public PropertyName findRenameByField(MapperConfig<?> config, AnnotatedField f, PropertyName implName) {
            return renameByField;
        }
    }

    @Test
    public void testPropertyNameMergeBasicCombination() {
        PropertyName name1 = PropertyName.construct("a", null);
        PropertyName name2 = PropertyName.construct("", "ns2");
        PropertyName merged = PropertyName.merge(name1, name2);
        assertNotNull(merged);
        assertEquals("a", merged.getSimpleName());
        assertEquals("ns2", merged.getNamespace());

        // If first has empty simple, second has explicit -> second should be returned as-is
        PropertyName emptyFirst = PropertyName.construct("", null);
        PropertyName explicitSecond = PropertyName.construct("b", "nsB");
        PropertyName merged2 = PropertyName.merge(emptyFirst, explicitSecond);
        assertSame(explicitSecond, merged2);

        // Both null -> null
        assertNull(PropertyName.merge(null, null));
    }

    @Test
    public void testPropertyNameMergeIdentitySelectionWhenPrimaryHasAll() {
        PropertyName primary = PropertyName.construct("p", "nsP");
        PropertyName secondary = PropertyName.construct("s", "nsS");
        PropertyName merged = PropertyName.merge(primary, secondary);
        // Since primary provides both non-empty parts, merge should return the same instance
        assertSame(primary, merged);
    }

    @Test
    public void testAnnotationIntrospectorPairMergesPrimaryEmptySecondaryExplicit() {
        // Primary simulates annotation with empty/default values
        PropertyName empty = PropertyName.construct("", "");
        FixedNamesIntrospector primary = new FixedNamesIntrospector(
                empty, empty, empty, empty, empty
        );

        // Secondary simulates explicit values from another annotation
