        // one null -> other
        PropertyName p = PropertyName.construct("p", "ns");
        assertSame(p, PropertyName.merge(p, null));
        assertSame(p, PropertyName.merge(null, p));

        // primary empty, secondary explicit -> use secondary (identity preserved)
        PropertyName primaryEmpty = PropertyName.construct("", null);
        PropertyName secondaryExplicit = PropertyName.construct("prop", "uri:ns1");
        PropertyName merged = PropertyName.merge(primaryEmpty, secondaryExplicit);
