        assertEquals("localOnly", combined.getSimpleName());
        assertEquals("uri:ns2", combined.getNamespace());
        assertNotSame(primarySimpleOnly, combined);
        assertNotSame(secondaryNsOnly, combined);

        // primary fully specified wins and identity preserved
        PropertyName name1 = PropertyName.construct("x", "ns1");
        PropertyName name2 = PropertyName.construct("y", "ns2");
        PropertyName mergedPrimaryWins = PropertyName.merge(name1, name2);
        assertSame(name1, mergedPrimaryWins);
        assertEquals("x", mergedPrimaryWins.getSimpleName());
        assertEquals("ns1", mergedPrimaryWins.getNamespace());

