        PropertyName primaryRename = PropertyName.construct("pLocal", null);

        StubIntrospector primary = new StubIntrospector(null, null, null, null, primaryRename);
        StubIntrospector secondary = new StubIntrospector(null, null, null, null, secondaryRename);

        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(primary, secondary);

        PropertyName result = pair.findRenameByField(null, null, null);
        assertNotNull(result);
        assertEquals("pLocal", result.getSimpleName());
        assertEquals("nsRen", result.getNamespace());
    }

