    static class StubIntrospector extends AnnotationIntrospector {
        private static final long serialVersionUID = 1L;

        private final PropertyName wrapperName;
        private final PropertyName renameByFieldName;

        StubIntrospector(PropertyName wrapperName) {
            this(wrapperName, null);
        }

        StubIntrospector(PropertyName wrapperName, PropertyName renameByFieldName) {
            this.wrapperName = wrapperName;
            this.renameByFieldName = renameByFieldName;
        }

        @Override
