        public PropertyName findRenameByField(MapperConfig<?> config, AnnotatedField f, PropertyName implName) {
            return renameByFieldName;
        }
    }

    @Test
    public void wrapperName_usesSecondaryWhenPrimaryUseDefault() {
        PropertyName primaryName = PropertyName.USE_DEFAULT;
        PropertyName secondaryName = PropertyName.construct("prop", "uri:ns1");

        AnnotationIntrospector primary = new StubIntrospector(primaryName);
        AnnotationIntrospector secondary = new StubIntrospector(secondaryName);

        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(primary, secondary);

        PropertyName result = pair.findWrapperName(null);

        // Since primary is "use default" (empty), secondary explicit values should be used
        assertSame(secondaryName, result);
        assertEquals("prop", result.getSimpleName());
        assertEquals("uri:ns1", result.getNamespace());
    }

    @Test
    public void wrapperName_mergesSimpleFromPrimaryNamespaceFromSecondary() {
        // Primary provides simple name but has empty namespace; Secondary provides namespace
        PropertyName primaryName = PropertyName.construct("p1", "");
        PropertyName secondaryName = PropertyName.construct("", "ns2");

        AnnotationIntrospector primary = new StubIntrospector(primaryName);
        AnnotationIntrospector secondary = new StubIntrospector(secondaryName);

        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(primary, secondary);

        PropertyName result = pair.findWrapperName(null);

        assertEquals("p1", result.getSimpleName());
        assertEquals("ns2", result.getNamespace());
        // New instance is expected since neither original fully matches merged parts
        assertNotSame(primaryName, result);
        assertNotSame(secondaryName, result);
    }

    @Test
    public void wrapperName_returnsPrimaryWhenPrimaryComplete() {
        // Primary has both non-empty parts; it should be returned as-is
        PropertyName primaryName = PropertyName.construct("p1", "ns1");
        PropertyName secondaryName = PropertyName.construct("ignored", "ignored");

        AnnotationIntrospector primary = new StubIntrospector(primaryName);
        AnnotationIntrospector secondary = new StubIntrospector(secondaryName);

        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(primary, secondary);

        PropertyName result = pair.findWrapperName(null);

        assertSame(primaryName, result);
        assertEquals("p1", result.getSimpleName());
        assertEquals("ns1", result.getNamespace());
    }

    @Test
    public void wrapperName_nullHandlingForEitherSide() {
        // Primary null => use secondary
        PropertyName secondaryName = PropertyName.construct("s", "nsS");
        AnnotationIntrospector primaryNull = new StubIntrospector(null);
        AnnotationIntrospector secondary = new StubIntrospector(secondaryName);
        AnnotationIntrospectorPair pair1 = new AnnotationIntrospectorPair(primaryNull, secondary);
        PropertyName result1 = pair1.findWrapperName(null);
        assertSame(secondaryName, result1);

        // Secondary null => use primary
        PropertyName primaryName = PropertyName.construct("p", "nsP");
        AnnotationIntrospector primary = new StubIntrospector(primaryName);
        AnnotationIntrospector secondaryNull = new StubIntrospector(null);
        AnnotationIntrospectorPair pair2 = new AnnotationIntrospectorPair(primary, secondaryNull);
        PropertyName result2 = pair2.findWrapperName(null);
        assertSame(primaryName, result2);
    }

    @Test
    public void findRenameByField_secondaryHasPrecedenceAndIsMergedFirst() {
        // For findRenameByField, AnnotationIntrospectorPair now merges with secondary first (higher precedence)
        PropertyName primaryRename = PropertyName.construct("primaryRename", "nsP");
        PropertyName secondaryRename = PropertyName.construct("secondaryRename", "nsS");

        AnnotationIntrospector primary = new StubIntrospector(null, primaryRename);
