        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(primary, secondary);

        PropertyName result = pair.findRenameByField(null, null, null);

        // Since both provide non-empty values and secondary has precedence, the result should be secondary
        assertSame(secondaryRename, result);
        assertEquals("secondaryRename", result.getSimpleName());
        assertEquals("nsS", result.getNamespace());
    }
}

