package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.core.Version;
import com.fasterxml.jackson.databind.AnnotationIntrospector;
import com.fasterxml.jackson.databind.PropertyName;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

public class AnnotationIntrospectorPairMergeTest {

    private static class StubIntrospector extends AnnotationIntrospector {
        private static final long serialVersionUID = 1L;

        private final PropertyName serName;
        private final PropertyName deserName;
        private final PropertyName wrapperName;
        private final PropertyName rootName;
        private final PropertyName renameByField;

        StubIntrospector(PropertyName serName,
                         PropertyName deserName,
                         PropertyName wrapperName,
                         PropertyName rootName,
                         PropertyName renameByField) {
            this.serName = serName;
            this.deserName = deserName;
            this.wrapperName = wrapperName;
            this.rootName = rootName;
            this.renameByField = renameByField;
        }

        @Override
        public Version version() {
            return Version.unknownVersion();
        }

        @Override
        public PropertyName findNameForSerialization(Annotated a) {
            return serName;
        }

        @Override
        public PropertyName findNameForDeserialization(Annotated a) {
            return deserName;
        }

        @Override
        public PropertyName findWrapperName(Annotated ann) {
            return wrapperName;
        }

        @Override
        public PropertyName findRootName(AnnotatedClass ac) {
            return rootName;
        }

        @Override
        public PropertyName findRenameByField(MapperConfig<?> config, AnnotatedField f, PropertyName implName) {
            return renameByField;
        }
    }

    @Test
    public void testFindNameForSerialization_PrimaryUseDefaultSecondaryExplicit() {
        PropertyName primary = PropertyName.USE_DEFAULT; // empty simple, null namespace
        PropertyName secondary = PropertyName.construct("prop", "uri:ns1");

        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(
                new StubIntrospector(primary, null, null, null, null),
                new StubIntrospector(secondary, null, null, null, null)
        );

        PropertyName result = pair.findNameForSerialization(null);
        assertNotNull(result);
        // With merge, explicit values from secondary should be used; should return same instance
        assertSame(secondary, result);
        assertEquals("prop", result.getSimpleName());
        assertEquals("uri:ns1", result.getNamespace());
    }

    @Test
    public void testFindNameForSerialization_CombinePartsFromPrimaryAndSecondary() {
        PropertyName primary = PropertyName.construct("x", ""); // explicit simple, empty namespace
        PropertyName secondary = PropertyName.construct("", "uri:ns"); // empty simple, explicit namespace

        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(
                new StubIntrospector(primary, null, null, null, null),
                new StubIntrospector(secondary, null, null, null, null)
        );

        PropertyName result = pair.findNameForSerialization(null);
        assertNotNull(result);
        assertEquals("x", result.getSimpleName());
        assertEquals("uri:ns", result.getNamespace());
        // Result should not be the same instance as either input since it merges parts
        assertNotSame(primary, result);
        assertNotSame(secondary, result);
    }

    @Test
    public void testFindNameForSerialization_BothNullReturnsNull() {
        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(
                new StubIntrospector(null, null, null, null, null),
                new StubIntrospector(null, null, null, null, null)
        );
        PropertyName result = pair.findNameForSerialization(null);
        assertNull(result);
    }

    @Test
    public void testFindNameForDeserialization_PrimaryEmptySecondaryExplicit() {
        PropertyName primary = PropertyName.construct("", ""); // both empty
        PropertyName secondary = PropertyName.construct("name", "ns");

        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(
                new StubIntrospector(null, primary, null, null, null),
                new StubIntrospector(null, secondary, null, null, null)
        );

        PropertyName result = pair.findNameForDeserialization(null);
        assertNotNull(result);
        assertSame(secondary, result);
        assertEquals("name", result.getSimpleName());
        assertEquals("ns", result.getNamespace());
    }

    @Test
    public void testFindWrapperName_CombineBehavior() {
        PropertyName primary = PropertyName.construct("local", ""); // local from primary
        PropertyName secondary = PropertyName.construct("", "uri:ns"); // ns from secondary

        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(
                new StubIntrospector(null, null, primary, null, null),
                new StubIntrospector(null, null, secondary, null, null)
        );

        PropertyName result = pair.findWrapperName(null);
        assertNotNull(result);
        assertEquals("local", result.getSimpleName());
        assertEquals("uri:ns", result.getNamespace());
    }

    @Test
    public void testFindRootName_CombineBehavior() {
        PropertyName primary = PropertyName.construct("", "p:ns"); // primary ns only
        PropertyName secondary = PropertyName.construct("root", ""); // secondary simple only

        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(
                new StubIntrospector(null, null, null, primary, null),
                new StubIntrospector(null, null, null, secondary, null)
        );

        PropertyName result = pair.findRootName(null);
        assertNotNull(result);
        assertEquals("root", result.getSimpleName());
        assertEquals("p:ns", result.getNamespace());
    }

    @Test
    public void testFindRenameByField_SecondaryPrecedenceWhenBothExplicit() {
        PropertyName fromSecondary = PropertyName.construct("secName", "nsSEC");
        PropertyName fromPrimary = PropertyName.construct("priName", "nsPRI");

        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(
                new StubIntrospector(null, null, null, null, fromPrimary),
                new StubIntrospector(null, null, null, null, fromSecondary)
        );

        // Order for findRenameByField is merge(secondary, primary), so secondary should take precedence
        PropertyName result = pair.findRenameByField(null, null, null);
        assertNotNull(result);
        assertSame(fromSecondary, result);
        assertEquals("secName", result.getSimpleName());
        assertEquals("nsSEC", result.getNamespace());
    }

    @Test
    public void testFindRenameByField_FallbackToPrimaryWhenSecondaryEmpty() {
        PropertyName fromSecondary = PropertyName.construct("", ""); // empty parts
        PropertyName fromPrimary = PropertyName.construct("priName", "nsPRI");

        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(
                new StubIntrospector(null, null, null, null, fromPrimary),
                new StubIntrospector(null, null, null, null, fromSecondary)
        );

        PropertyName result = pair.findRenameByField(null, null, null);
        assertNotNull(result);
        assertSame(fromPrimary, result);
        assertEquals("priName", result.getSimpleName());
        assertEquals("nsPRI", result.getNamespace());
    }
}

