package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.ObjectWriter;
import com.fasterxml.jackson.databind.SerializationFeature;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

/**
 * Tests for handling Enums where some constants' toString() return null,
 * ensuring that obtaining an ObjectWriter and serializing does not fail
 * and that null toString() values are coerced to empty strings when using
 * toString-based enum serialization.
 *
 * Covers fix for databind#4355.
 */
public class EnumValuesNullToString4355Test {

    // Enum with one constant whose toString() returns null
    enum NullToStringEnum {
        ALPHA,
        UNDEFINED {
            @Override
            public String toString() {
                return null;
            }
        }
    }

    @Test
    public void testObtainWriterAndSerializeWithDefaultNamingShouldNotFail() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // Should not throw when obtaining ObjectWriter, even if some toString() return null
        ObjectWriter w = mapper.writerFor(NullToStringEnum.class);
        assertNotNull(w);

        // Default serialization uses Enum.name(), not toString()
        assertEquals("\"ALPHA\"", w.writeValueAsString(NullToStringEnum.ALPHA));
        assertEquals("\"UNDEFINED\"", w.writeValueAsString(NullToStringEnum.UNDEFINED));
    }

    @Test
    public void testSerializeUsingToStringNullCoercedToEmpty() throws Exception {
        ObjectMapper mapper = new ObjectMapper()
                .enable(SerializationFeature.WRITE_ENUMS_USING_TO_STRING);

        // Should not throw when obtaining ObjectWriter
        ObjectWriter w = mapper.writerFor(NullToStringEnum.class);
        assertNotNull(w);

        // Using toString(): normal constant uses default Enum.toString() -> name
        assertEquals("\"ALPHA\"", w.writeValueAsString(NullToStringEnum.ALPHA));

        // For constant whose toString() returns null, result is coerced to empty string
        assertEquals("\"\"", w.writeValueAsString(NullToStringEnum.UNDEFINED));
    }
}

