package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.JsonAnyGetter;
import com.fasterxml.jackson.annotation.JsonAnySetter;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Assert;
import org.junit.Test;

import java.util.HashMap;
import java.util.Map;

/**
 * Tests for issue #4316: Ensure ThrowableDeserializer properly instantiates the Throwable
 * when encountering the "message" property even if there is no String-arg constructor,
 * so that @JsonAnySetter can safely set additional properties without NPE.
 */
public class ThrowableDeserializerAnySetter4316Test {

    // Reproduction class: extends Exception without declaring its own constructors,
    // meaning it has a default (no-arg) constructor but no String-arg constructor.
    // The @JsonAnySetter should collect unknown fields; @JsonAnyGetter serializes them.
    public static class Problem extends Exception {
        @JsonAnySetter
        @JsonAnyGetter
        public Map<String, Object> additionalProperties = new HashMap<>();
    }

    @Test
    public void testDeserializeWithMessageThenAnySetterFromJsonString() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // Construct JSON where "message" comes before the additional properties.
        // Prior to the fix, encountering "message" did not instantiate when no String-creator,
        // leading to a null instance and NPE when applying @JsonAnySetter.
        String json = "{ \"message\": \"boom\", \"additional\": \"value\" }";

        Problem result = mapper.readValue(json, Problem.class);

        // Verify deserialization succeeded and additional property was applied via @JsonAnySetter
        Assert.assertNotNull(result);
        Assert.assertNotNull(result.additionalProperties);
        Assert.assertEquals("value", result.additionalProperties.get("additional"));

        // Since there is no String-arg constructor, the message should not be set via constructor.
        // It will remain null (default Exception() sets message to null).
        Assert.assertNull(result.getMessage());
    }

    @Test
    public void testRoundTripSerializationDeserializationWithAnyProperties() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        Problem original = new Problem();
        original.additionalProperties.put("extra", "data");

        // Round-trip through JSON
        String json = mapper.writeValueAsString(original);
        Problem result = mapper.readValue(json, Problem.class);

        // Ensure no NPE occurred and the additional properties are preserved
        Assert.assertNotNull(result);
        Assert.assertNotNull(result.additionalProperties);
        Assert.assertEquals("data", result.additionalProperties.get("extra"));
    }
}

