package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.annotation.JsonAnyGetter;
import com.fasterxml.jackson.annotation.JsonAnySetter;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;

import java.util.LinkedHashMap;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests to verify that deserializing a Throwable subclass with @JsonAnySetter does not
 * throw a NullPointerException and that additional properties are correctly captured.
 * This specifically targets the fix for issue #4316 where ThrowableDeserializer must
 * instantiate the Throwable when encountering the 'message' property even if it does not
 * have a String-creator, so that the any-setter can operate on a non-null instance.
 */
public class ThrowableAnySetterNpe4316Test {

    // Throwable subclass without a String-creator (only default constructor) and with Any-Getter/Setter
    static class ProblemNoStringCtor extends Exception {
        private static final long serialVersionUID = 1L;

        private final Map<String, Object> additional = new LinkedHashMap<>();

        public ProblemNoStringCtor() { }

        // Standard Any-Getter on a method
        @JsonAnyGetter
        public Map<String, Object> any() {
            return additional;
        }

        // Standard Any-Setter on a method
        @JsonAnySetter
        public void add(String key, Object value) {
            additional.put(key, value);
        }
    }

    @Test
    public void testDeserializeThrowableWithAnySetter_NoStringCreator_NoNPE() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // Prepare instance with additional properties to be serialized via @JsonAnyGetter
        ProblemNoStringCtor problem = new ProblemNoStringCtor();
        problem.add("additional", "additional-value");

        // Serialize first to ensure JSON order includes "message" (which will be null) before any-getter content
        String json = mapper.writeValueAsString(problem);

        // Deserialization must not throw NPE and must populate the additional properties map
        ProblemNoStringCtor result = mapper.readValue(json, ProblemNoStringCtor.class);

        assertNotNull(result, "Deserialized Throwable instance should not be null");
        assertNotNull(result.any(), "Additional properties map should not be null");
        assertEquals(1, result.any().size(), "Additional properties should contain one entry");
        assertEquals("additional-value", result.any().get("additional"),
                "Additional property value should be preserved after round-trip");
    }

    @Test
    public void testDeserializeEmptyJsonInstantiatesThrowable() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // With no properties at all, deserializer should instantiate using default constructor at the end
        ProblemNoStringCtor result = mapper.readValue("{}", ProblemNoStringCtor.class);

        assertNotNull(result, "Deserialized Throwable instance should not be null for empty JSON");
        assertTrue(result.any().isEmpty(), "No additional properties should be populated for empty JSON");
    }
}

