import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.List;
import java.util.TreeSet;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests for verifying that CollectionDeserializer respects Nulls.SKIP for content when
 * values deserialize to null due to:
 * - READ_UNKNOWN_ENUM_VALUES_AS_NULL (unknown enum values)
 * - FAIL_ON_INVALID_SUBTYPE disabled (invalid subtypes treated as null)
 *
 * Also verifies that _tryToAddNull respects _skipNullValues (does not try to add null to e.g. TreeSet).
 */
public class CollectionDeserializerNullsSkipTest {

    enum Color {
        RED, GREEN, BLUE
    }

    static class EnumListContainer {
        @JsonSetter(contentNulls = Nulls.SKIP)
        public List<Color> colors = new ArrayList<>();
    }

    static class EnumTreeSetContainer {
        @JsonSetter(contentNulls = Nulls.SKIP)
        public TreeSet<Color> colors = new TreeSet<>();
    }

    @JsonIdentityInfo(generator = ObjectIdGenerators.PropertyGenerator.class, property = "id")
    @JsonTypeInfo(use = JsonTypeInfo.Id.NAME, include = JsonTypeInfo.As.PROPERTY, property = "type")
    @JsonSubTypes({
            @JsonSubTypes.Type(name = "ok", value = Impl.class)
    })
    static abstract class Base {
        public int id;
    }

    @JsonTypeName("ok")
    static class Impl extends Base {
        public String name;
    }

    static class PolyContainer {
        @JsonSetter(contentNulls = Nulls.SKIP)
        public List<Base> values = new ArrayList<>();
    }

    @Test
    public void testUnknownEnumSingleValueIsSkippedForList() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.ACCEPT_SINGLE_VALUE_AS_ARRAY);
        mapper.enable(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_AS_NULL);

        String json = "{\"colors\":\"PURPLE\"}";
        EnumListContainer result = mapper.readValue(json, EnumListContainer.class);

        assertNotNull(result);
        assertNotNull(result.colors);
        // With Nulls.SKIP and unknown enum treated as null, element should be skipped entirely
        assertEquals(0, result.colors.size(), "Unknown enum value should be skipped, resulting in empty list");
    }

    @Test
    public void testUnknownEnumSingleValueIsSkippedForTreeSet_noException() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.ACCEPT_SINGLE_VALUE_AS_ARRAY);
        mapper.enable(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_AS_NULL);

        String json = "{\"colors\":\"PURPLE\"}";
        EnumTreeSetContainer result = mapper.readValue(json, EnumTreeSetContainer.class);

        assertNotNull(result);
        assertNotNull(result.colors);
        // With Nulls.SKIP, _tryToAddNull should return early and not attempt to add null to TreeSet
        assertTrue(result.colors.isEmpty(), "Unknown enum value should be skipped, resulting in empty TreeSet");
    }

    @Test
    public void testInvalidSubtypeIsSkippedWithObjectIdHandling() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        // Do not fail on invalid subtype: treat as null
        mapper.disable(DeserializationFeature.FAIL_ON_INVALID_SUBTYPE);

        String json = "{ \"values\": [ " +
                "{ \"type\": \"unknown\", \"id\": 1 }, " + // invalid subtype -> null
                "{ \"type\": \"ok\", \"id\": 2, \"name\": \"valid\" } " +
                "] }";

        PolyContainer result = mapper.readValue(json, PolyContainer.class);

        assertNotNull(result);
        assertNotNull(result.values);
        // With content Nulls.SKIP, the invalid subtype (deserialized as null) should be skipped
        assertEquals(1, result.values.size(), "Invalid subtype should be skipped, only valid element should remain");
        assertTrue(result.values.get(0) instanceof Impl, "Remaining element should be of known subtype Impl");
        Impl impl = (Impl) result.values.get(0);
        assertEquals(2, impl.id);
        assertEquals("valid", impl.name);
    }
}

