package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.databind.json.JsonMapper;
import com.fasterxml.jackson.databind.exc.InvalidDefinitionException;
import com.fasterxml.jackson.databind.PropertyNamingStrategies;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * Tests for issue databind#4302: ensure that when a PropertyNamingStrategy is configured,
 * enum properties are not renamed during introspection, avoiding conflicts between enum
 * constants and instance fields with the same logical name.
 */
public class EnumPropertyNamingStrategy4302Test {

    // Reproduction enum: has a constant "FOO" and an instance field "foo"
    enum ProblemEnum {
        FOO(0);

        public final int foo;

        ProblemEnum(int foo) {
            this.foo = foo;
        }
    }

    @Test
    public void testEnumDeserializationWithSnakeCaseSkipsEnumPropertyRenaming() throws Exception {
        ObjectMapper mapper = JsonMapper.builder()
                .propertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE)
                .build();

        // Prior to the fix, this could fail with InvalidDefinitionException complaining about
        // "Multiple fields representing property 'foo'".
        // After the fix, enum properties are skipped for renaming, so deserialization should succeed.
        ProblemEnum result = mapper.readValue("\"FOO\"", ProblemEnum.class);
        assertEquals(ProblemEnum.FOO, result);
    }

    @Test
    public void testAnotherEnumValueDeserialization() throws Exception {
        // Additional enum constant to ensure general behavior remains correct
        // We'll dynamically add a mapper and deserialize existing constant again to ensure stability
        ObjectMapper mapper = JsonMapper.builder()
                .propertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE)
                .build();

        ProblemEnum result = mapper.readValue("\"FOO\"", ProblemEnum.class);
        assertEquals(ProblemEnum.FOO, result);
    }

    @Test
    public void testDoesNotThrowInvalidDefinitionException() throws Exception {
        ObjectMapper mapper = JsonMapper.builder()
                .propertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE)
                .build();

        // Ensure no InvalidDefinitionException is thrown during deserialization/introspection
        try {
            mapper.readValue("\"FOO\"", ProblemEnum.class);
        } catch (InvalidDefinitionException e) {
            throw new AssertionError("InvalidDefinitionException should not be thrown after the fix, but was: " + e.getMessage(), e);
        }
    }
}

