package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.annotation.JsonAutoDetect;
import com.fasterxml.jackson.annotation.PropertyAccessor;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.MapperFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Assert;
import org.junit.Test;

import java.util.Map;

public class RequireSettersForGettersTest {

    static class DataB {
        private int readonly = 1;
        private int readwrite = 2;

        public int getReadonly() {
            return readonly;
        }

        public int getReadwrite() {
            return readwrite;
        }

        public void setReadwrite(int readwrite) {
            this.readwrite = readwrite;
        }
    }

    @Test
    public void testRequireSettersDropsGetterOnlyPropertyByDefault() throws Exception {
        // GIVEN: Default visibility (private fields are not visible)
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(MapperFeature.REQUIRE_SETTERS_FOR_GETTERS);

        DataB input = new DataB();

        // WHEN
        String json = mapper.writeValueAsString(input);

        // THEN: "readonly" (getter-only, backing field not visible) must be excluded,
        // while "readwrite" (has both getter and setter) must be included.
        Map<String, Object> result = new ObjectMapper().readValue(json, new TypeReference<Map<String, Object>>() {});
        Assert.assertFalse("Getter-only property 'readonly' should be excluded", result.containsKey("readonly"));
        Assert.assertTrue("Property 'readwrite' should be included", result.containsKey("readwrite"));
        Assert.assertEquals(2, ((Number) result.get("readwrite")).intValue());
        Assert.assertEquals("Only one property should be serialized", 1, result.size());
    }

    @Test
    public void testVisibleFieldAllowsGetterOnlyPropertyWithFeature() throws Exception {
        // GIVEN: Make fields visible so that a visible field can qualify for deserialization
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(MapperFeature.REQUIRE_SETTERS_FOR_GETTERS);
        mapper.setVisibility(PropertyAccessor.FIELD, JsonAutoDetect.Visibility.ANY);

        DataB input = new DataB();

        // WHEN
        String json = mapper.writeValueAsString(input);

        // THEN: With fields visible, the getter-only 'readonly' has a visible field and should be included.
        Map<String, Object> result = new ObjectMapper().readValue(json, new TypeReference<Map<String, Object>>() {});
        Assert.assertTrue("Getter-only property 'readonly' should be included when backing field is visible",
                result.containsKey("readonly"));
        Assert.assertTrue("Property 'readwrite' should be included", result.containsKey("readwrite"));
        Assert.assertEquals(1, ((Number) result.get("readonly")).intValue());
        Assert.assertEquals(2, ((Number) result.get("readwrite")).intValue());
    }
}

