package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.databind.JsonNode;
import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

public class ObjectNodeFindValuesAndParentsTest {

    @Test
    public void testFindValuesAndFindParentsCollectAllMatches() {
        JsonNodeFactory f = JsonNodeFactory.instance;

        // Build tree:
        // {
        //   "target": 1,
        //   "foo": { "target": 2, "bar": { "target": 3 }, "other": { "notTarget": 99 } },
        //   "baz": { "qux": { "target": 4 } },
        //   "target2": { "target": 5 },
        //   "arr": [ { "target": 7 }, { "x": { "target": 8 } }, { "target": { "target": 9 } } ],
        //   "nested": { "target": { "target": 10 }, "x": 11 }
        // }
        ObjectNode root = f.objectNode();
        root.put("target", 1);

        ObjectNode foo = root.putObject("foo");
        foo.put("target", 2);
        ObjectNode bar = foo.putObject("bar");
        bar.put("target", 3);
        foo.putObject("other").put("notTarget", 99);

        ObjectNode baz = root.putObject("baz");
        ObjectNode qux = baz.putObject("qux");
        qux.put("target", 4);

        ObjectNode target2 = root.putObject("target2");
        target2.put("target", 5);

        ArrayNode arr = root.putArray("arr");
        ObjectNode arr0 = f.objectNode();
        arr0.put("target", 7);
        arr.add(arr0);

        ObjectNode arr1 = f.objectNode();
        ObjectNode arr1x = arr1.putObject("x");
        arr1x.put("target", 8);
        arr.add(arr1);

        ObjectNode arr2 = f.objectNode();
        ObjectNode arr2TargetVal = f.objectNode();
        arr2TargetVal.put("target", 9);
        arr2.set("target", arr2TargetVal);
        arr.add(arr2);

        ObjectNode nested = root.putObject("nested");
        ObjectNode nestedTargetVal = f.objectNode();
        nestedTargetVal.put("target", 10);
        nested.set("target", nestedTargetVal);
        nested.put("x", 11);

        // Validate findValues collects all matches in document order and does not descend into matched values
        List<JsonNode> values = root.findValues("target", null);
        assertNotNull(values, "findValues should return a non-null list");
        assertEquals(9, values.size(), "Should collect all 9 'target' values across the tree");

        assertTrue(values.get(0).isInt()); assertEquals(1, values.get(0).intValue());
        assertTrue(values.get(1).isInt()); assertEquals(2, values.get(1).intValue());
        assertTrue(values.get(2).isInt()); assertEquals(3, values.get(2).intValue());
        assertTrue(values.get(3).isInt()); assertEquals(4, values.get(3).intValue());
        assertTrue(values.get(4).isInt()); assertEquals(5, values.get(4).intValue());
        assertTrue(values.get(5).isInt()); assertEquals(7, values.get(5).intValue());
        assertTrue(values.get(6).isInt()); assertEquals(8, values.get(6).intValue());

        // Next two are object values for fields named "target"; their inner "target" fields must NOT be traversed/added
        JsonNode v7 = values.get(7);
        assertTrue(v7.isObject());
        assertTrue(v7.has("target"));
        assertEquals(9, v7.get("target").asInt(), "Inner 'target' exists inside the matched value but should not have been counted separately");

        JsonNode v8 = values.get(8);
        assertTrue(v8.isObject());
        assertTrue(v8.has("target"));
        assertEquals(10, v8.get("target").asInt());

        // Validate findParents returns all parents of matches in document order, without stopping early
        List<JsonNode> parents = root.findParents("target", null);
        assertNotNull(parents);
        assertEquals(9, parents.size(), "Should collect parents for all 9 matches");

        assertSame(root, parents.get(0));
        assertSame(foo, parents.get(1));
        assertSame(bar, parents.get(2));
        assertSame(qux, parents.get(3));
        assertSame(target2, parents.get(4));
        assertSame(arr0, parents.get(5));
        assertSame(arr1x, parents.get(6));
        assertSame(arr2, parents.get(7));
        assertSame(nested, parents.get(8));
    }

    @Test
    public void testFindValuesAsTextCollectsAllMatches() {
        JsonNodeFactory f = JsonNodeFactory.instance;

        // Build tree with textual matches and a top-level match to ensure no early return
        // {
        //   "target": "a",
        //   "foo": { "target": "b", "x": 1 },
        //   "bar": { "y": { "target": "c" } },
        //   "none": { "target2": "z" }
        // }
        ObjectNode root = f.objectNode();
        root.put("target", "a");

        ObjectNode foo = root.putObject("foo");
        foo.put("target", "b");
        foo.put("x", 1);

        ObjectNode bar = root.putObject("bar");
        ObjectNode y = bar.putObject("y");
        y.put("target", "c");

        root.putObject("none").put("target2", "z");

        List<String> texts = root.findValuesAsText("target", null);
        assertNotNull(texts);
        assertEquals(3, texts.size(), "Should collect all 3 textual 'target' values");
        assertEquals("a", texts.get(0));
        assertEquals("b", texts.get(1));
        assertEquals("c", texts.get(2));
    }
}

