package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.databind.BeanDescription;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.type.ArrayType;
import com.fasterxml.jackson.databind.DeserializationConfig;
import com.fasterxml.jackson.databind.module.SimpleModule;
import org.junit.jupiter.api.Test;

import java.util.Collections;
import java.util.HashSet;
import java.util.Set;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

public class PrimitiveArrayDeserializerModifierTest {

    static class RecordingModifier extends BeanDeserializerModifier {
        static final Set<Class<?>> seenRawArrayTypes = Collections.synchronizedSet(new HashSet<>());

        static void reset() {
            seenRawArrayTypes.clear();
        }

        @Override
        public JsonDeserializer<?> modifyArrayDeserializer(DeserializationConfig config,
                                                           ArrayType type,
                                                           BeanDescription beanDesc,
                                                           JsonDeserializer<?> deserializer) {
            // Record the raw array class for which the modifier is invoked
            seenRawArrayTypes.add(type.getRawClass());
            // Return the original deserializer (we only want to verify the hook is invoked)
            return deserializer;
        }
    }

    static class TestBean {
        public byte[] pBytes;
        public Byte[] oBytes;
        public String[] strings;
    }

    @Test
    public void shouldApplyModifierToPrimitiveAndStringArrays() throws Exception {
        RecordingModifier.reset();

        SimpleModule module = new SimpleModule();
        module.setDeserializerModifier(new RecordingModifier());

        ObjectMapper mapper = new ObjectMapper();
        mapper.registerModule(module);

        String json = "{\"pBytes\":[1,2,3],\"oBytes\":[1,2],\"strings\":[\"a\",\"b\"]}";
        TestBean bean = mapper.readValue(json, TestBean.class);

        // Verify normal deserialization still works
        assertArrayEquals(new byte[] { 1, 2, 3 }, bean.pBytes, "Primitive byte[] should deserialize as-is");
        assertArrayEquals(new Byte[] { 1, 2 }, bean.oBytes, "Boxed Byte[] should deserialize as-is");
        assertArrayEquals(new String[] { "a", "b" }, bean.strings, "String[] should deserialize as-is");

        // Core assertions: modifier must be called for primitive and String arrays (and object arrays)
        assertTrue(RecordingModifier.seenRawArrayTypes.contains(byte[].class),
                "Expected modifyArrayDeserializer to be called for primitive byte[]");
        assertTrue(RecordingModifier.seenRawArrayTypes.contains(Byte[].class),
                "Expected modifyArrayDeserializer to be called for boxed Byte[]");
        assertTrue(RecordingModifier.seenRawArrayTypes.contains(String[].class),
                "Expected modifyArrayDeserializer to be called for String[]");
    }
}

