package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.annotation.JsonSubTypes;
import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;

import static org.junit.Assert.*;

/**
 * Tests to ensure that external type id handling works correctly when a parent property
 * is annotated with @JsonIgnoreProperties. This validates that BeanDeserializerBase
 * preserves the _externalTypeIdHandler across copy constructors used by contextualization,
 * such as when applying ignoreUnknown or by-name inclusion/exclusion.
 */
public class ExternalTypeWithIgnorePropertiesTest {

    // Polymorphic base type
    public interface SubChild { }

    // One concrete subtype
    public static class SubChildA implements SubChild { }

    // Holder that uses EXTERNAL_PROPERTY type info for 'subChild', using 'childType' as the external type property
    public static class Child {
        public String childType;

        // Include external type id via sibling property "childType"
        @JsonTypeInfo(use = JsonTypeInfo.Id.NAME, include = JsonTypeInfo.As.EXTERNAL_PROPERTY, property = "childType")
        @JsonSubTypes({
                @JsonSubTypes.Type(value = SubChildA.class, name = "A")
        })
        public SubChild subChild;

        // A property that may be ignored via by-name inclusion on the parent property
        public String ignoredVal;
    }

    // Parent variant where the 'child' property ignores all unknown properties
    public static class ParentIgnoreUnknown {
        @JsonIgnoreProperties(ignoreUnknown = true)
        public Child child;
    }

    // Parent variant where the 'child' property ignores specific properties by name
    public static class ParentIgnoreByName {
        @JsonIgnoreProperties(value = { "ignoredVal" })
        public Child child;
    }

    @Test
    public void testExternalTypeWithIgnoreUnknown() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // 'bogus' is unknown to Child and should be ignored due to @JsonIgnoreProperties(ignoreUnknown = true)
        String json = "{ \"child\": { \"childType\": \"A\", \"subChild\": { }, \"bogus\": 123 } }";

        ParentIgnoreUnknown result = mapper.readValue(json, ParentIgnoreUnknown.class);
        assertNotNull(result);
        assertNotNull(result.child);
        assertNotNull("subChild should be deserialized using external type id", result.child.subChild);
        assertTrue("Expected SubChildA instance", result.child.subChild instanceof SubChildA);
    }

    @Test
    public void testExternalTypeWithByNameInclusion() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // 'ignoredVal' exists as a property on Child but should be excluded via by-name inclusion rules
        String json = "{ \"child\": { \"childType\": \"A\", \"subChild\": { }, \"ignoredVal\": \"to-be-ignored\" } }";

        ParentIgnoreByName result = mapper.readValue(json, ParentIgnoreByName.class);
        assertNotNull(result);
        assertNotNull(result.child);
        assertNotNull("subChild should be deserialized using external type id", result.child.subChild);
        assertTrue("Expected SubChildA instance", result.child.subChild instanceof SubChildA);

        // Since 'ignoredVal' was excluded by @JsonIgnoreProperties on the property, it should not be set
        assertNull("ignoredVal should have been ignored and left null", result.child.ignoredVal);
    }
}

