package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.jsontype.impl.LaissezFaireSubTypeValidator;
import org.junit.Test;

import java.util.concurrent.atomic.AtomicReference;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class DefaultTypingEnumSupportTest {

    enum Frequency {
        DAILY, WEEKLY
    }

    @Test
    public void testEnumTypingRoundTripWithNonFinalAndEnums() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.activateDefaultTyping(
                LaissezFaireSubTypeValidator.instance,
                ObjectMapper.DefaultTyping.NON_FINAL_AND_ENUMS,
                JsonTypeInfo.As.WRAPPER_ARRAY
        );

        String json = mapper.writeValueAsString(Frequency.DAILY);

        // Should include type info wrapper array with class id and enum name
        assertTrue("Expected wrapper array with type info", json.startsWith("["));
        assertTrue("Expected enum name in JSON", json.contains("\"DAILY\""));
        assertTrue("Expected type id to contain enum class name", json.contains("Frequency"));

        Frequency back = mapper.readValue(json, Frequency.class);
        assertEquals(Frequency.DAILY, back);
    }

    @Test
    public void testEnumNotTypedWithNonFinal() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.activateDefaultTyping(
                LaissezFaireSubTypeValidator.instance,
                ObjectMapper.DefaultTyping.NON_FINAL,
                JsonTypeInfo.As.WRAPPER_ARRAY
        );

        String json = mapper.writeValueAsString(Frequency.DAILY);

        // With NON_FINAL, enums (being final) must not be wrapped with type info
        assertEquals("\"DAILY\"", json);

        Frequency back = mapper.readValue(json, Frequency.class);
        assertEquals(Frequency.DAILY, back);
    }

    @Test
    public void testEnumInsideReferenceGetsTypedWithNonFinalAndEnums() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.activateDefaultTyping(
                LaissezFaireSubTypeValidator.instance,
                ObjectMapper.DefaultTyping.NON_FINAL_AND_ENUMS,
                JsonTypeInfo.As.WRAPPER_ARRAY
        );

        AtomicReference<Frequency> ref = new AtomicReference<>(Frequency.DAILY);
        String json = mapper.writeValueAsString(ref);

        // Since NON_FINAL_AND_ENUMS unwraps reference types and allows enums,
        // the referenced enum should be wrapped with type info.
        assertTrue("Expected wrapper array for referenced enum", json.startsWith("["));
        assertTrue("Expected enum name in JSON", json.contains("\"DAILY\""));
        assertTrue("Expected type id to contain enum class name", json.contains("Frequency"));

        AtomicReference<Frequency> back = mapper.readValue(
                json,
                new TypeReference<AtomicReference<Frequency>>() {}
        );
        assertEquals(Frequency.DAILY, back.get());
    }
}

