package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.databind.JsonNode;
import org.junit.Test;

import static org.junit.Assert.*;

public class JsonNodeWithObjectStringTest {

    @Test
    public void testWithObjectAcceptsPropertyName() {
        ObjectNode root = JsonNodeFactory.instance.objectNode();

        // Using a simple property name should create and return an ObjectNode at that property
        ObjectNode child = root.withObject("foo");
        assertNotNull(child);
        assertTrue(child.isObject());

        // Should be accessible via get and be the same instance
        JsonNode fromGet = root.get("foo");
        assertNotNull(fromGet);
        assertTrue(fromGet.isObject());
        assertSame(child, fromGet);

        // Repeated calls should return the same node
        ObjectNode child2 = root.withObject("foo");
        assertSame(child, child2);

        // Modifications should reflect under the property
        child.put("a", 1);
        assertEquals(1, root.path("foo").path("a").intValue());
    }

    @Test
    public void testWithObjectAcceptsJsonPointerAndEmptyPointer() {
        ObjectNode root = JsonNodeFactory.instance.objectNode();

        // Using a JsonPointer expression should create nested structure
        ObjectNode leaf = root.withObject("/foo/bar");
        assertNotNull(leaf);
        assertTrue(leaf.isObject());

        // Validate nested structure exists and returned node matches nested path
        JsonNode fooNode = root.path("foo");
        assertTrue(fooNode.isObject());
        JsonNode barNode = fooNode.path("bar");
        assertTrue(barNode.isObject());
        assertSame(leaf, barNode);

        // Modify leaf and ensure changes are visible via the path
        leaf.put("x", 123);
        assertEquals(123, root.path("foo").path("bar").path("x").intValue());

        // Empty string should be treated as a valid JsonPointer (current node)
        ObjectNode sameAsRoot = root.withObject("");
        assertSame(root, sameAsRoot);
    }

    @Test
    public void testWithObjectTreatsNonPointerWithSlashAsPropertyName() {
        ObjectNode root = JsonNodeFactory.instance.objectNode();

        // "foo/bar" is not a valid JsonPointer (no leading slash), so treat as literal property name
        ObjectNode node = root.withObject("foo/bar");
        assertNotNull(node);
        assertTrue(node.isObject());

        // Ensure property with exact name exists
        assertTrue(root.has("foo/bar"));
        assertSame(node, root.get("foo/bar"));

        // Ensure it did NOT create nested "foo" property
        assertFalse(root.has("foo"));
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testBaseJsonNodeImplementationThrowsForNonObjectNodes() {
        // TextNode (a non-ObjectNode) should not implement withObject(String) and use base behavior
        TextNode text = TextNode.valueOf("abc");
        text.withObject("ignored");
    }
}

