package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.databind.JsonNode;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

public class ObjectNodeWithObjectStringTest {

    @Test
    public void testWithObjectWithPlainPropertyNameCreatesChildAndReturnsIt() {
        ObjectNode root = JsonNodeFactory.instance.objectNode();

        ObjectNode child = root.withObject("foo");
        assertNotNull(child);
        assertTrue(root.has("foo"));
        JsonNode fetched = root.get("foo");
        assertNotNull(fetched);
        assertTrue(fetched.isObject());

        // Returned node should reflect changes in the tree
        child.put("a", 1);
        JsonNode leaf = root.at("/foo/a");
        assertTrue(leaf.isInt());
        assertEquals(1, leaf.intValue());

        // Using JsonPointer for the same path should return the same object
        ObjectNode childViaPointer = root.withObject("/foo");
        assertSame(child, childViaPointer);
    }

    @Test
    public void testWithObjectWithJsonPointerCreatesNestedObjectAndReturnsIt() {
        ObjectNode root = JsonNodeFactory.instance.objectNode();

        ObjectNode nested = root.withObject("/foo/bar");
        assertNotNull(nested);
        assertTrue(root.path("foo").isObject());
        assertTrue(root.path("foo").path("bar").isObject());

        // Verify returned node is the same as the nested node in the tree
        nested.put("answer", 42);
        JsonNode answerNode = root.at("/foo/bar/answer");
        assertTrue(answerNode.isInt());
        assertEquals(42, answerNode.intValue());
    }

    @Test
    public void testWithObjectEmptyStringPointerReturnsRootNode() {
        ObjectNode root = JsonNodeFactory.instance.objectNode();

        ObjectNode result = root.withObject("");
        // Empty JsonPointer should refer to current node itself
        assertSame(root, result);
        assertEquals(0, root.size());
        assertNull(root.get("")); // ensure no "" property was created
    }

    @Test
    public void testWithObjectNonPointerContainingSlashTreatedAsPropertyName() {
        ObjectNode root = JsonNodeFactory.instance.objectNode();

        ObjectNode child = root.withObject("a/b");
        assertNotNull(child);
        assertTrue(root.has("a/b"));
        assertTrue(root.get("a/b").isObject());

        // Ensure that JsonPointer "/a/b" was NOT created as nested structure
        JsonNode viaPointer = root.at("/a/b");
        assertTrue(viaPointer.isMissingNode(), "Should not have created nested nodes for non-pointer 'a/b'");
    }

    @Test
    public void testWithObjectOnNonObjectNodeThrowsUnsupportedOperationException() {
        TextNode scalar = TextNode.valueOf("x");
        assertThrows(UnsupportedOperationException.class, () -> scalar.withObject("foo"));
        assertThrows(UnsupportedOperationException.class, () -> scalar.withObject("/foo"));
    }
}

