        assertTrue(child.isObject(), "Returned node should be an ObjectNode");
        JsonNode gotten = root.get("obj");
        assertNotNull(gotten, "Property 'obj' should now exist");
        assertTrue(gotten.isObject(), "Property 'obj' should be an ObjectNode");
        assertSame(child, gotten, "Returned ObjectNode should be the same instance as the property's value");
    }

