import java.util.Optional;
import java.util.OptionalInt;

import static org.junit.jupiter.api.Assertions.*;

public class BeanUtilOptionalSupportTest {

    @Test
    public void checkUnsupportedTypeForOptionalInt() {
        JavaType type = TypeFactory.defaultInstance().constructType(OptionalInt.class);
        String msg = BeanUtil.checkUnsupportedType(type);

        assertNotNull(msg, "Expected a non-null message for OptionalInt");
        assertTrue(msg.startsWith("Java 8 optional type"),
                "Message should indicate Java 8 optional type");
        assertTrue(msg.contains("java.util.OptionalInt"),
                "Message should include the OptionalInt type name");
        assertTrue(msg.contains("com.fasterxml.jackson.datatype:jackson-datatype-jdk8"),
                "Message should suggest registering the JDK8 module");
    }

    @Test
    public void checkUnsupportedTypeForOptionalGeneric() {
        JavaType type = TypeFactory.defaultInstance()
                .constructParametricType(Optional.class, String.class);
        String msg = BeanUtil.checkUnsupportedType(type);

        assertNotNull(msg, "Expected a non-null message for Optional<T>");
        assertTrue(msg.startsWith("Java 8 optional type"),
                "Message should indicate Java 8 optional type");
        assertTrue(msg.contains("java.util.Optional"),
                "Message should include the Optional type name");
        assertTrue(msg.contains("com.fasterxml.jackson.datatype:jackson-datatype-jdk8"),
                "Message should suggest registering the JDK8 module");
    }

