    public void isJava8OptionalClassRecognition() {
        assertTrue(BeanUtil.isJava8OptionalClass(OptionalInt.class),
                "isJava8OptionalClass should be true for OptionalInt");
        assertTrue(BeanUtil.isJava8OptionalClass(Optional.class),
                "isJava8OptionalClass should be true for Optional");
        assertFalse(BeanUtil.isJava8OptionalClass(String.class),
                "isJava8OptionalClass should be false for non-optional types");
