package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.exc.InvalidDefinitionException;
import com.fasterxml.jackson.databind.JsonMappingException;

import org.junit.Test;

import java.util.Optional;
import java.util.OptionalDouble;
import java.util.OptionalInt;
import java.util.OptionalLong;

import static org.junit.Assert.*;

public class BeanUtilJava8OptionalTest {

    public static class BeanWithOptionalInt {
        public OptionalInt value;

        public BeanWithOptionalInt() { }
    }

    @Test
    public void testIsJava8OptionalClassVariants() {
        // Should detect all Java 8 Optional variants
        assertTrue("Optional should be detected as Java 8 optional",
                BeanUtil.isJava8OptionalClass(Optional.class));
        assertTrue("OptionalInt should be detected as Java 8 optional",
                BeanUtil.isJava8OptionalClass(OptionalInt.class));
        assertTrue("OptionalLong should be detected as Java 8 optional",
                BeanUtil.isJava8OptionalClass(OptionalLong.class));
        assertTrue("OptionalDouble should be detected as Java 8 optional",
                BeanUtil.isJava8OptionalClass(OptionalDouble.class));

        // Should not detect unrelated classes
        assertFalse("String should not be detected as Java 8 optional",
                BeanUtil.isJava8OptionalClass(String.class));
    }

    @Test
    public void testCheckUnsupportedTypeMessageForOptionalInt() {
        ObjectMapper mapper = new ObjectMapper();
        JavaType t = mapper.getTypeFactory().constructType(OptionalInt.class);
        String msg = BeanUtil.checkUnsupportedType(t);
        assertNotNull("checkUnsupportedType should return a helpful message for OptionalInt without JDK8 module", msg);
        assertTrue("Message should mention Java 8 optional", msg.contains("Java 8 optional"));
        assertTrue("Message should include the type name", msg.contains("java.util.OptionalInt"));
        assertTrue("Message should suggest the JDK8 datatype module",
                msg.contains("com.fasterxml.jackson.datatype:jackson-datatype-jdk8"));
    }

    @Test
    public void testDeserializationFailsWithHelpfulMessageForOptionalIntRootType() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        try {
            mapper.readValue("1", OptionalInt.class);
            fail("Expected failure when deserializing OptionalInt without JDK8 module");
        } catch (InvalidDefinitionException e) {
            String msg = e.getMessage();
            assertTrue("Exception message should mention Java 8 optional", msg.contains("Java 8 optional"));
            assertTrue("Exception message should include the type name", msg.contains("java.util.OptionalInt"));
            assertTrue("Exception message should suggest the JDK8 datatype module",
                    msg.contains("com.fasterxml.jackson.datatype:jackson-datatype-jdk8"));
        } catch (JsonMappingException e) {
