package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.exc.UnrecognizedPropertyException;
import org.junit.Test;

import static org.junit.Assert.*;

/**
 * Tests for [databind#4071]: ensure that when deserializing a Throwable subtype that
 * lacks a single-String constructor (has only a default constructor), the "message"
 * property is ignored instead of causing an UnrecognizedPropertyException.
 */
public class ThrowableDeserializer4071Test {

    public static class DefaultOnlyException extends Exception {
        private static final long serialVersionUID = 1L;

        public DefaultOnlyException() {
            super();
        }
    }

    @Test
    public void testMessageIgnoredForDefaultCtorThrowable() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        // Ensure unknown properties would fail if encountered
        mapper.enable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES);

        // "message" should be ignored (skipped) for Throwable subtypes without String-arg ctor
        String json = "{\"message\":\"oops\"}";
        DefaultOnlyException e = mapper.readValue(json, DefaultOnlyException.class);

        assertNotNull(e);
        // Since only default ctor is used, message should remain null
        assertNull(e.getMessage());
    }

    @Test
    public void testMessageCaseInsensitiveIgnoredAndOtherUnknownStillFails() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES);

        // "Message" (different case) should be ignored, but another unknown property should still fail
        String json = "{\"Message\":\"oops\", \"bogus\": 3}";
        try {
            mapper.readValue(json, DefaultOnlyException.class);
            fail("Should fail due to unknown property 'bogus'");
        } catch (UnrecognizedPropertyException ex) {
            assertEquals("bogus", ex.getPropertyName());
        }
    }
}

