    public void testLocaleFromEmptyStringWithAcceptEmptyAsNullObjectEnabled() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.configure(DeserializationFeature.ACCEPT_EMPTY_STRING_AS_NULL_OBJECT, true);

        Locale result = mapper.readValue("\"\"", Locale.class);

        // After the fix, empty string should be converted via TryConvert for OtherScalar (Locale),
        // resulting in Locale.ROOT, not null.
        assertEquals(Locale.ROOT, result);
    }

    @Test
    public void testIntegerFromEmptyStringWithAcceptEmptyAsNullObjectEnabledIsNull() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.configure(DeserializationFeature.ACCEPT_EMPTY_STRING_AS_NULL_OBJECT, true);

        Integer result = mapper.readValue("\"\"", Integer.class);

        // For classic scalars (e.g., Integer), empty string with ACCEPT_EMPTY_STRING_AS_NULL_OBJECT
        // should still coerce to null.
        assertNull(result);
    }
}

