package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import org.junit.Test;

import java.util.List;

import static org.junit.Assert.*;

public class TypeParserGuardrailsTest {

    private static String buildNestedLists(int depth) {
        StringBuilder sb = new StringBuilder(depth * 20 + 32);
        for (int i = 0; i < depth; i++) {
            sb.append("java.util.List<");
        }
        sb.append("java.lang.String");
        for (int i = 0; i < depth; i++) {
            sb.append(">");
        }
        return sb.toString();
    }

    @Test
    public void testParseRejectsTooLongInputWithTruncatedMessage() {
        // Build a string longer than 64,000 characters to trigger length guard
        int tooLongLength = 64001; // MAX_TYPE_LENGTH + 1
        StringBuilder sb = new StringBuilder(tooLongLength);
        for (int i = 0; i < tooLongLength; i++) {
            sb.append('A');
        }
        String longCanonical = sb.toString();

        TypeFactory tf = TypeFactory.defaultInstance();
        TypeParser parser = new TypeParser(tf);

        try {
            parser.parse(longCanonical);
            fail("Expected IllegalArgumentException for too-long canonical type string");
        } catch (IllegalArgumentException e) {
            String msg = e.getMessage();
            assertNotNull(msg);
            // Should be the new format and reason
            assertTrue("Message should mention failure to parse type", msg.contains("Failed to parse type "));
            assertTrue("Message should mention too long with exact length",
                    msg.contains("too long (64001 characters), maximum length allowed: 64000"));
            // Should use truncation helper which adds a truncated marker and has a specific typo "charaters"
            assertTrue("Message should include truncated marker", msg.contains("[truncated "));
            assertTrue("Message should include 'charaters' typo from truncation helper",
                    msg.contains("charaters"));
        }
    }

    @Test
    public void testParseRejectsTooDeepNesting() {
        // Build a type with 1001 nested parameterized levels to exceed MAX_TYPE_NESTING (1000)
        String tooDeep = buildNestedLists(1001);

        TypeFactory tf = TypeFactory.defaultInstance();
        TypeParser parser = new TypeParser(tf);

        try {
            parser.parse(tooDeep);
            fail("Expected IllegalArgumentException for excessive nesting");
        } catch (IllegalArgumentException e) {
            String msg = e.getMessage();
            assertNotNull(msg);
            assertTrue("Message should start with failure to parse", msg.contains("Failed to parse type "));
            assertTrue("Message should indicate excessive nesting",
                    msg.contains("too deeply nested; exceeds maximum of 1000 nesting levels"));
            // Also ensure it includes the '(remaining: ...)' part from the new _problem format
            assertTrue("Message should include remaining token info", msg.contains("(remaining: "));
        }
    }

    @Test
    public void testParseAtNestingLimitSucceeds() {
        // Build a type with exactly 1000 nested parameterized levels which should be allowed
        final int atLimit = 1000;
        String atLimitType = buildNestedLists(atLimit);

        TypeFactory tf = TypeFactory.defaultInstance();
        TypeParser parser = new TypeParser(tf);

        JavaType t = parser.parse(atLimitType);
        assertNotNull("Type should be parsed successfully at nesting limit", t);
        assertEquals("Top-level raw class should be List", List.class, t.getRawClass());

