        JavaType curr = t;
        for (int i = 0; i < atLimit; i++) {
            assertNotNull("Content type at depth " + i + " should not be null", curr.getContentType());
            curr = curr.getContentType();
        }
        assertEquals("Innermost raw class should be String", String.class, curr.getRawClass());
    }
}

