package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.module.SimpleModule;
import com.fasterxml.jackson.databind.type.TypeFactory;
import org.junit.Test;

import java.io.IOException;
import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.Assert.*;

public class StdNodeBasedDeserializerUpdatingTest {

    // Simple POJO for testing
    public static class MyPojo {
        public int a;
        public String name;
    }

    // Deserializer that overrides the new 3-arg convert to perform in-place updates
    static class UpdatingMyPojoDeserializer extends StdNodeBasedDeserializer<MyPojo> {
        private static final long serialVersionUID = 1L;

        static final AtomicInteger callsConvert2 = new AtomicInteger(0);
        static final AtomicInteger callsConvert3 = new AtomicInteger(0);

        protected UpdatingMyPojoDeserializer() {
            super(TypeFactory.defaultInstance().constructType(MyPojo.class));
        }

        @Override
        public MyPojo convert(JsonNode root, DeserializationContext ctxt) throws IOException {
            // Should NOT be called for updating scenario when 3-arg convert is overridden
            callsConvert2.incrementAndGet();
            MyPojo p = new MyPojo();
            if (root.has("a")) {
                p.a = root.get("a").asInt();
            }
            if (root.has("name")) {
                p.name = root.get("name").asText();
            }
            return p;
        }

        @Override
        public MyPojo convert(JsonNode root, DeserializationContext ctxt, MyPojo intoValue) throws IOException {
            // This is the new method added by the patch; should be used by deserialize(jp, ctxt, T)
            callsConvert3.incrementAndGet();
            if (root.has("a")) {
                intoValue.a = root.get("a").asInt(intoValue.a);
            }
            if (root.has("name")) {
                intoValue.name = root.get("name").asText(intoValue.name);
            }
            return intoValue;
        }
    }

    // Deserializer that DOES NOT override the new 3-arg convert; default implementation should call handleBadMerge()
    // and then fall back to 2-arg convert(JsonNode, DeserializationContext)
    static class ReplacingMyPojoDeserializer extends StdNodeBasedDeserializer<MyPojo> {
        private static final long serialVersionUID = 1L;

        static final AtomicInteger callsConvert2 = new AtomicInteger(0);

        protected ReplacingMyPojoDeserializer() {
            super(TypeFactory.defaultInstance().constructType(MyPojo.class));
        }

        @Override
        public MyPojo convert(JsonNode root, DeserializationContext ctxt) throws IOException {
            callsConvert2.incrementAndGet();
            MyPojo p = new MyPojo();
            if (root.has("a")) {
                p.a = root.get("a").asInt();
            }
            if (root.has("name")) {
                p.name = root.get("name").asText();
            }
            return p;
        }
    }

    private static void resetCounters() {
        UpdatingMyPojoDeserializer.callsConvert2.set(0);
        UpdatingMyPojoDeserializer.callsConvert3.set(0);
        ReplacingMyPojoDeserializer.callsConvert2.set(0);
    }

    @Test
    public void testReaderForUpdatingUsesNewConvertOverload() throws Exception {
        resetCounters();

        ObjectMapper mapper = new ObjectMapper();
        SimpleModule module = new SimpleModule();
        UpdatingMyPojoDeserializer deser = new UpdatingMyPojoDeserializer();
        module.addDeserializer(MyPojo.class, deser);
        mapper.registerModule(module);

        MyPojo existing = new MyPojo();
        existing.a = 1;
        existing.name = "orig";

        String json = "{\"a\":7,\"name\":\"upd\"}";

        // This should trigger StdNodeBasedDeserializer.deserialize(jp, ctxt, T),
        // which converts parser to JsonNode and calls our 3-arg convert(..)
        MyPojo result = mapper.readerForUpdating(existing).readValue(json);

        // Ensure same instance is updated and returned
        assertSame(existing, result);
        assertEquals(7, existing.a);
        assertEquals("upd", existing.name);

        // Ensure 3-arg convert was used and 2-arg convert was not used during updating
        assertEquals(1, UpdatingMyPojoDeserializer.callsConvert3.get());
        assertEquals(0, UpdatingMyPojoDeserializer.callsConvert2.get());
    }

    @Test
    public void testDefaultConvertFallbackWhenNotOverridden() throws Exception {
        resetCounters();

        ObjectMapper mapper = new ObjectMapper();
        // Ensure that if bad-merge is signaled, it won't fail the test (ignore bad merge warning)
        mapper.configure(MapperFeature.IGNORE_MERGE_FOR_UNMERGEABLE, true);

        SimpleModule module = new SimpleModule();
        ReplacingMyPojoDeserializer deser = new ReplacingMyPojoDeserializer();
        module.addDeserializer(MyPojo.class, deser);
        mapper.registerModule(module);

        MyPojo existing = new MyPojo();
        existing.a = 2;
        existing.name = "e1";

        String json = "{\"a\":5,\"name\":\"n2\"}";

        // Since ReplacingMyPojoDeserializer does not override the 3-arg convert,
        // StdNodeBasedDeserializer.deserialize(jp, ctxt, T) will call the default
        // convert(root, ctxt, newValue) which should delegate to convert(root, ctxt)
        // ignoring the existing value (no in-place update).
        MyPojo result = mapper.readerForUpdating(existing).readValue(json);

        // Existing value should remain unchanged
        assertEquals(2, existing.a);
        assertEquals("e1", existing.name);

        // Returned value should be a newly created instance with JSON-applied values
        assertNotSame(existing, result);
        assertEquals(5, result.a);
        assertEquals("n2", result.name);

        // Ensure the 2-arg convert was invoked exactly once via the default fallback
        assertEquals(1, ReplacingMyPojoDeserializer.callsConvert2.get());
    }
}

