package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.JsonCreator;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.exc.MismatchedInputException;
import org.junit.Test;

import static org.junit.Assert.*;

public class UnwrapSingleValueArraysEnumAndBeanTest {

    // Enum using factory-based creator to trigger FactoryBasedEnumDeserializer path
    enum MyEnum {
        FOO, BAR;

        @JsonCreator
        public static MyEnum fromValue(String v) {
            // Should receive non-null String when unwrapping single-element array
            assertNotNull("Creator should get non-null value", v);
            return MyEnum.valueOf(v);
        }
    }

    static class MyBean {
        public int a;

        public MyBean() { }
    }

    @Test
    public void testFactoryBasedEnumUnwrapsSingleElementArray() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);

        MyEnum e = mapper.readValue("[\"FOO\"]", MyEnum.class);
        assertEquals(MyEnum.FOO, e);
    }

    @Test
    public void testFactoryBasedEnumRejectsMultipleValuesWhenUnwrapping() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);

        try {
            mapper.readValue("[\"FOO\",\"BAR\"]", MyEnum.class);
            fail("Expected MismatchedInputException for multiple values in single-value array unwrapping");
        } catch (MismatchedInputException e) {
            // Expected: verify it is indeed a mismatched input due to array content
            String msg = e.getMessage();
            assertNotNull(msg);
            // Message content may vary; just ensure it's about array/single-value mismatch
            assertTrue(msg.contains("array") || msg.contains("Array"));
        }
    }

    @Test
    public void testBeanDeserializerRejectsDeeplyNestedArrayWhenUnwrapping() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);

        try {
            // Top-level array unwrapping is enabled, but the first element itself is another array:
            // [[{"a":1}]] should be rejected with a clear error about nested arrays
            mapper.readValue("[[{\"a\":1}]]", MyBean.class);
            fail("Expected MismatchedInputException due to deeply-nested array with UNWRAP_SINGLE_VALUE_ARRAYS");
        } catch (MismatchedInputException e) {
            String msg = e.getMessage();
            assertNotNull(msg);
            // Verify the error references the single-wrapper constraint
            assertTrue(msg.contains("only single wrapper allowed"));
            assertTrue(msg.contains("UNWRAP_SINGLE_VALUE_ARRAYS"));
        }
    }
}

