        try {
            mapper.readValue("[\"FOO\",\"BAR\"]", MyEnum.class);
            fail("Expected MismatchedInputException due to extra elements in single-value array");
        } catch (MismatchedInputException e) {
            // Expected: verify that factory was not called due to error before invoking creator
            // (handleMissingEndArrayForSingle should trigger before calling the factory)
            // If the implementation changes, this assertion ensures the end-array check is enforced.
            assertEquals("Factory should not be invoked when array has extra elements", null, MyEnum.lastArg);
