        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);

        Bean bean = mapper.readValue("[{\"a\":1}]", Bean.class);
        assertEquals("Bean property should be set when unwrapping single-value array", 1, bean.a);
    }
}

