package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.JsonAnySetter;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Assert;
import org.junit.Test;

import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;

public class AnySetterNullMapInitTest {

    static class BeanWithRawMapAnyField {
        @JsonAnySetter
        public Map<String, String> other; // intentionally left null
    }

    static class BeanWithHashMapAnyField {
        @JsonAnySetter
        public HashMap<String, String> other; // intentionally left null
    }

    // A custom Map type that should not be supported by JDKValueInstantiators
    static class UnsupportedMap extends HashMap<String, String> {
        private static final long serialVersionUID = 1L;
    }

    static class BeanWithUnsupportedMapAnyField {
        @JsonAnySetter
        public UnsupportedMap other; // intentionally left null
    }

    @Test
    public void testAnySetterRawMapFieldIsAutoInitialized() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        BeanWithRawMapAnyField bean = mapper.readValue("{\"a\":\"1\"}", BeanWithRawMapAnyField.class);

        Assert.assertNotNull("Map field should be initialized", bean.other);
        Assert.assertTrue("Map field should be LinkedHashMap when declared as raw Map",
                bean.other instanceof LinkedHashMap);
        Assert.assertEquals(1, bean.other.size());
        Assert.assertEquals("1", bean.other.get("a"));
    }

    @Test
    public void testAnySetterConcreteJdkMapFieldIsAutoInitialized() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        BeanWithHashMapAnyField bean = mapper.readValue("{\"a\":\"1\"}", BeanWithHashMapAnyField.class);

        Assert.assertNotNull("Map field should be initialized", bean.other);
        Assert.assertTrue("Map field should be HashMap when declared as HashMap",
                bean.other instanceof HashMap);
        Assert.assertEquals(1, bean.other.size());
        Assert.assertEquals("1", bean.other.get("a"));
    }

    @Test
    public void testAnySetterUnsupportedMapTypeThrowsClearException() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        try {
            mapper.readValue("{\"a\":\"1\"}", BeanWithUnsupportedMapAnyField.class);
            Assert.fail("Expected JsonMappingException for unsupported Map type");
        } catch (JsonMappingException e) {
            String msg = e.getMessage();
            Assert.assertNotNull(msg);
            // Ensure descriptive error message without NPE (ctxt null handled)
            Assert.assertTrue("Error message should indicate failure to create instance",
                    msg.contains("Cannot create an instance of"));
            Assert.assertTrue("Error message should mention any-setter",
                    msg.contains("any-setter"));
            Assert.assertTrue("Error message should include the property name",
                    msg.contains("'other'"));
            Assert.assertTrue("Error message should include the unsupported type name",
                    msg.contains(UnsupportedMap.class.getName()));
        }
    }
}

