package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.JsonAnySetter;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;

import java.util.AbstractMap;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;

import static org.junit.Assert.*;

public class AnySetterNullMapTest {

    // Bean with a raw Map field annotated as any-setter; initially null
    static class RawMapAnyBean {
        @JsonAnySetter
        public Map<String, String> other;
    }

    // Bean with a specific JDK Map type (HashMap) annotated as any-setter; initially null
    static class HashMapAnyBean {
        @JsonAnySetter
        public HashMap<String, String> extra;
    }

    // Custom, unsupported Map type (no default constructor) to trigger clear error
    static class BadMap extends AbstractMap<String, String> {
        public BadMap(int dummy) { }
        @Override
        public Set<Entry<String, String>> entrySet() {
            return Collections.emptySet();
        }
    }

    static class BadMapAnyBean {
        @JsonAnySetter
        public BadMap bad;
    }

    @Test
    public void testFieldAnySetterInitializesNullRawMapAsLinkedHashMap() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        RawMapAnyBean bean = mapper.readValue("{\"a\":\"b\",\"c\":\"d\"}", RawMapAnyBean.class);

        assertNotNull("Map should be auto-initialized", bean.other);
        assertTrue("Raw Map should default to LinkedHashMap", bean.other instanceof LinkedHashMap);
        assertEquals("b", bean.other.get("a"));
        assertEquals("d", bean.other.get("c"));
        assertEquals(2, bean.other.size());
    }

    @Test
    public void testFieldAnySetterInitializesNullSpecificJdkMap() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        HashMapAnyBean bean = mapper.readValue("{\"k1\":\"v1\"}", HashMapAnyBean.class);

        assertNotNull("Map should be auto-initialized", bean.extra);
        assertTrue("Specific JDK Map type should be used", bean.extra instanceof HashMap);
        assertEquals("v1", bean.extra.get("k1"));
        assertEquals(1, bean.extra.size());
    }

    @Test
    public void testFieldAnySetterUnsupportedMapTypeThrowsClearMessage() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        try {
            mapper.readValue("{\"x\":\"y\"}", BadMapAnyBean.class);
            fail("Expected JsonMappingException for unsupported any-setter Map type");
        } catch (JsonMappingException e) {
            String msg = e.getMessage();
            assertNotNull(msg);
            assertTrue("Exception message should mention inability to create instance",
                    msg.contains("Cannot create an instance of"));
            assertTrue("Exception message should include the unsupported type name",
                    msg.contains(BadMap.class.getName()));
            assertTrue("Exception message should include the any-setter property name",
                    msg.contains("'bad'"));
        }
    }

    @Test
    public void testJsonMappingExceptionFromWithNullDeserializationContext() {
        RuntimeException cause = new RuntimeException("root");
        JsonMappingException e = JsonMappingException.from((DeserializationContext) null, "test-message", cause);
        assertNotNull(e);
        // Ensure message is preserved and no NPE due to null context
        assertTrue(e.getMessage().contains("test-message"));
        // With null context, processor should be null
        assertNull(e.getProcessor());

        JsonMappingException e2 = JsonMappingException.from((DeserializationContext) null, "another-message");
        assertNotNull(e2);
        assertTrue(e2.getMessage().contains("another-message"));
        assertNull(e2.getProcessor());
    }
}

