import com.fasterxml.jackson.databind.exc.MismatchedInputException;
import com.fasterxml.jackson.databind.type.LogicalType;

public class IntToFloatCoercionTest {

    @Test
    public void testIntToFloatFailForFloatDoubleAndBigDecimal() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.Fail);

        // Float wrapper
        expectFailOnIntToFloat(mapper, Float.class);
        // float primitive
        expectFailOnIntToFloat(mapper, Float.TYPE);

        // Double wrapper
        expectFailOnIntToFloat(mapper, Double.class);
        // double primitive
        expectFailOnIntToFloat(mapper, Double.TYPE);

        // BigDecimal
        expectFailOnIntToFloat(mapper, BigDecimal.class);
    }

    @Test
    public void testIntToFloatAsNullForWrappersAndPrimitives() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.AsNull);

        // Wrappers should become null
        Float f = mapper.readValue("11", Float.class);
        assertNull(f);
        Double d = mapper.readValue("11", Double.class);
        assertNull(d);
        BigDecimal bd = mapper.readValue("11", BigDecimal.class);
        assertNull(bd);

        // Primitives should become their default "empty"/null-equivalent value
        float pf = mapper.readValue("11", Float.TYPE);
        assertEquals(0.0f, pf, 0.0f);
        double pd = mapper.readValue("11", Double.TYPE);
        assertEquals(0.0d, pd, 0.0d);
    }

    @Test
    public void testIntToFloatAsEmptyForPrimitives() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.AsEmpty);

        // Primitives should become their "empty" value
        float pf = mapper.readValue("11", Float.TYPE);
        assertEquals(0.0f, pf, 0.0f);

        double pd = mapper.readValue("11", Double.TYPE);
        assertEquals(0.0d, pd, 0.0d);
    }

    @Test
    public void testDefaultAllowsIntToFloatCoercion() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        Float f = mapper.readValue("11", Float.class);
        assertEquals(Float.valueOf(11.0f), f);

        float pf = mapper.readValue("11", Float.TYPE);
        assertEquals(11.0f, pf, 0.0f);

        Double d = mapper.readValue("11", Double.class);
        assertEquals(Double.valueOf(11.0d), d);

        double pd = mapper.readValue("11", Double.TYPE);
        assertEquals(11.0d, pd, 0.0d);

        BigDecimal bd = mapper.readValue("11", BigDecimal.class);
        assertEquals(new BigDecimal("11"), bd);
    }

