package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.cfg.CoercionAction;
import com.fasterxml.jackson.databind.cfg.CoercionInputShape;
import com.fasterxml.jackson.databind.exc.MismatchedInputException;
import com.fasterxml.jackson.databind.type.LogicalType;
import org.junit.Assert;
import org.junit.Test;

import java.math.BigDecimal;

public class IntToFloatCoercionTest {

    private void expectFail(ObjectMapper mapper, String json, Class<?> targetType) {
        try {
            mapper.readValue(json, targetType);
            Assert.fail("Expected MismatchedInputException for " + targetType.getName());
        } catch (MismatchedInputException e) {
            // Optional: ensure message indicates integer-to-float coercion was blocked
            String msg = e.getMessage();
            Assert.assertTrue("Exception message should mention integer value", msg == null || msg.contains("Integer value (11)"));
        } catch (Exception e) {
            Assert.fail("Expected MismatchedInputException, got: " + e);
        }
    }

    @Test
    public void testIntToFloatCoercionFailForAllFloatTypes() {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.Fail);

        // Primitive float
        expectFail(mapper, "11", float.class);
        // Wrapper Float
        expectFail(mapper, "11", Float.class);
        // Primitive double
        expectFail(mapper, "11", double.class);
        // Wrapper Double
        expectFail(mapper, "11", Double.class);
        // BigDecimal
        expectFail(mapper, "11", BigDecimal.class);
    }

    @Test
    public void testIntToFloatCoercionAsNull() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.AsNull);

        // Primitive float -> 0.0f (null-equivalent for primitive)
        float pf = mapper.readValue("11", float.class);
        Assert.assertEquals(0.0f, pf, 0.0f);

        // Wrapper Float -> null
        Float wf = mapper.readValue("11", Float.class);
        Assert.assertNull(wf);

        // Primitive double -> 0.0d
        double pd = mapper.readValue("11", double.class);
        Assert.assertEquals(0.0d, pd, 0.0d);

        // Wrapper Double -> null
        Double wd = mapper.readValue("11", Double.class);
        Assert.assertNull(wd);

        // BigDecimal -> null
        BigDecimal bd = mapper.readValue("11", BigDecimal.class);
        Assert.assertNull(bd);
    }

    @Test
    public void testIntToFloatCoercionAsEmptyForPrimitives() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.AsEmpty);

        // Primitive float -> 0.0f (empty-equivalent for primitive)
        float pf = mapper.readValue("11", float.class);
        Assert.assertEquals(0.0f, pf, 0.0f);

        // Primitive double -> 0.0d
        double pd = mapper.readValue("11", double.class);
        Assert.assertEquals(0.0d, pd, 0.0d);
    }

    @Test
    public void testDefaultAcceptsIntegerToFloatCoercion() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // With no special coercion config, integer -> float/double/BigDecimal should coerce normally
        Assert.assertEquals(11.0f, mapper.readValue("11", float.class), 0.0f);
        Assert.assertEquals(Float.valueOf(11.0f), mapper.readValue("11", Float.class));

        Assert.assertEquals(11.0d, mapper.readValue("11", double.class), 0.0d);
        Assert.assertEquals(Double.valueOf(11.0d), mapper.readValue("11", Double.class));

        Assert.assertEquals(BigDecimal.valueOf(11L), mapper.readValue("11", BigDecimal.class));
    }
}

