package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.JsonMerge;
import com.fasterxml.jackson.annotation.JsonSubTypes;
import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;

import static org.junit.Assert.*;

/**
 * Tests for verifying polymorphic property merging behavior in SettableBeanProperty.deserializeWith:
 * - Merging into existing value for the same concrete subtype should succeed and preserve non-overridden fields.
 * - No "Cannot merge polymorphic property" exception should be thrown for polymorphic properties.
 */
public class SettableBeanPropertyPolymorphicMergeTest {

    @JsonTypeInfo(use = JsonTypeInfo.Id.NAME, include = JsonTypeInfo.As.PROPERTY, property = "type")
    @JsonSubTypes({
            @JsonSubTypes.Type(value = Sub1.class, name = "s1"),
            @JsonSubTypes.Type(value = Sub2.class, name = "s2")
    })
    public static abstract class Base {
        // abstract base for polymorphic handling
    }

    public static class Sub1 extends Base {
        public String name;
        public int count;
    }

    public static class Sub2 extends Base {
        public String title;
        public boolean flag;
    }

    public static class Container {
        @JsonMerge
        public Base base;
    }

    @Test
    public void testPolymorphicMergeSameSubtype() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        // Required so that "type" property (used for polymorphic type info) is ignored when delegating
        // to concrete subtype deserializer during merge.
        mapper.disable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES);

        // Existing instance with concrete subtype Sub1
        Container original = new Container();
        Sub1 existing = new Sub1();
        existing.name = "original-name";
        existing.count = 1;
        original.base = existing;

        // Incoming JSON uses same subtype ("s1") and updates only 'count'
        String json = "{ \"base\": { \"type\": \"s1\", \"count\": 7 } }";

        Container updated = mapper.readerForUpdating(original).readValue(json);

        // Should not create a new Container nor a new Sub1: merge into existing instances
        assertSame(original, updated);
        assertTrue(updated.base instanceof Sub1);
        assertSame(existing, updated.base);

        Sub1 merged = (Sub1) updated.base;
        // 'name' should be preserved (not provided in incoming JSON)
        assertEquals("original-name", merged.name);
        // 'count' should be updated from JSON
        assertEquals(7, merged.count);
    }

    @Test
    public void testPolymorphicMergeDifferentSubtypeDoesNotThrow() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.disable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES);

        Container original = new Container();
        Sub1 existing = new Sub1();
        existing.name = "keep-me";
        existing.count = 42;
        original.base = existing;

        // Incoming JSON declares a different subtype ("s2") with fields not present in Sub1.
        // With the patch, this should not throw "Cannot merge polymorphic property";
        // instead, it will delegate to Sub1 deserializer and ignore unknown fields.
        String json = "{ \"base\": { \"type\": \"s2\", \"title\": \"other\", \"flag\": true } }";

        Container updated = mapper.readerForUpdating(original).readValue(json);

        assertSame(original, updated);
        assertTrue(updated.base instanceof Sub1);
        assertSame(existing, updated.base);

        // Since incoming JSON had no overlapping fields with Sub1, nothing changes.
        Sub1 merged = (Sub1) updated.base;
        assertEquals("keep-me", merged.name);
        assertEquals(42, merged.count);
    }
}

