package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.annotation.JsonCreator;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.annotation.JsonSetter;
import com.fasterxml.jackson.annotation.Nulls;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Assert;
import org.junit.Test;

import java.util.ArrayList;
import java.util.List;

public class NullsSkipSetOnBufferedPropsTest {

    // Bean that uses a setter (MethodProperty) and a property-based creator
    static class MiddleMethod {
        private List<String> list1 = new ArrayList<>();
        private final String field1;

        @JsonCreator
        public MiddleMethod(@JsonProperty("field1") String field1) {
            this.field1 = field1;
        }

        @JsonSetter(value = "list1", nulls = Nulls.SKIP)
        public void setList1(List<String> list1) {
            this.list1 = list1;
        }

        public List<String> getList1() {
            return list1;
        }

        public String getField1() {
            return field1;
        }
    }

    // Bean that uses a public field (FieldProperty) and a property-based creator
    static class MiddleField {
        @JsonSetter(value = "list1", nulls = Nulls.SKIP)
        public List<String> list1 = new ArrayList<>();

        private final String field1;

        @JsonCreator
        public MiddleField(@JsonProperty("field1") String field1) {
            this.field1 = field1;
        }

        public String getField1() {
            return field1;
        }
    }

    @Test
    public void testMethodPropertySkipNullDuringPropertyBasedCreation() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // "list1": null comes before the creator property "field1", so it will be buffered
        String json = "{ \"list1\": null, \"field1\": \"data\" }";

        MiddleMethod middle = mapper.readValue(json, MiddleMethod.class);

        // After the patch, null should be skipped and the initialized list should remain non-null
        Assert.assertNotNull("list1 should not be null when Nulls.SKIP is configured", middle.getList1());
        Assert.assertTrue("list1 should remain the initialized empty list", middle.getList1().isEmpty());
        Assert.assertEquals("data", middle.getField1());
    }

    @Test
    public void testFieldPropertySkipNullDuringPropertyBasedCreation() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // "list1": null comes before the creator property "field1", so it will be buffered
        String json = "{ \"list1\": null, \"field1\": \"data\" }";

        MiddleField middle = mapper.readValue(json, MiddleField.class);

        // After the patch, null should be skipped and the initialized list should remain non-null
        Assert.assertNotNull("list1 should not be null when Nulls.SKIP is configured", middle.list1);
        Assert.assertTrue("list1 should remain the initialized empty list", middle.list1.isEmpty());
        Assert.assertEquals("data", middle.getField1());
    }
}

