package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.databind.AnnotationIntrospector;
import com.fasterxml.jackson.databind.PropertyName;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;

public class AnnotationIntrospectorPairMergeTest {

    private static class SimpleAI extends NopAnnotationIntrospector {
        private final PropertyName rootName;
        private final PropertyName wrapperName;
        private final PropertyName nameForSer;
        private final PropertyName nameForDeser;
        private final PropertyName renameByField;

        SimpleAI(PropertyName rootName,
                 PropertyName wrapperName,
                 PropertyName nameForSer,
                 PropertyName nameForDeser,
                 PropertyName renameByField) {
            this.rootName = rootName;
            this.wrapperName = wrapperName;
            this.nameForSer = nameForSer;
            this.nameForDeser = nameForDeser;
            this.renameByField = renameByField;
        }

        @Override
        public PropertyName findRootName(AnnotatedClass ac) {
            return rootName;
        }

        @Override
        public PropertyName findWrapperName(Annotated ann) {
            return wrapperName;
        }

        @Override
        public PropertyName findNameForSerialization(Annotated a) {
            return nameForSer;
        }

        @Override
        public PropertyName findNameForDeserialization(Annotated a) {
            return nameForDeser;
        }

        @Override
        public PropertyName findRenameByField(MapperConfig<?> config, AnnotatedField f, PropertyName implName) {
            return renameByField;
        }
    }

    @Test
    public void testRootNameMergesSecondaryValuesWhenPrimaryEmpty() {
        // Primary provides empty simple name and empty namespace; secondary provides explicit values
        SimpleAI primary = new SimpleAI(
                new PropertyName("", ""),
                null,
                null,
                null,
                null
        );
        SimpleAI secondary = new SimpleAI(
                new PropertyName("prop", "uri:ns1"),
                null,
                null,
                null,
                null
        );

        AnnotationIntrospector pair = AnnotationIntrospectorPair.create(primary, secondary);
        PropertyName result = pair.findRootName(null);

        assertEquals("prop", result.getSimpleName());
        assertEquals("uri:ns1", result.getNamespace());
    }

    @Test
    public void testWrapperNamePrefersPrimaryNonEmpty() {
        // Both provide values; primary should take precedence
        SimpleAI primary = new SimpleAI(
                null,
                new PropertyName("wrapP", "nsP"),
                null,
                null,
                null
        );
        SimpleAI secondary = new SimpleAI(
                null,
                new PropertyName("wrapS", "nsS"),
                null,
                null,
                null
        );

        AnnotationIntrospector pair = AnnotationIntrospectorPair.create(primary, secondary);
        PropertyName result = pair.findWrapperName(null);

        assertEquals("wrapP", result.getSimpleName());
        assertEquals("nsP", result.getNamespace());
    }

    @Test
    public void testNameForSerializationTreatsUseDefaultAsEmpty() {
        // Primary returns USE_DEFAULT (treated as empty); secondary provides explicit values
        SimpleAI primary = new SimpleAI(
                null,
                null,
                PropertyName.USE_DEFAULT,
                null,
                null
        );
        SimpleAI secondary = new SimpleAI(
                null,
                null,
                new PropertyName("serName", "nsSer"),
                null,
                null
        );

        AnnotationIntrospector pair = AnnotationIntrospectorPair.create(primary, secondary);
        PropertyName result = pair.findNameForSerialization(null);

        assertEquals("serName", result.getSimpleName());
        assertEquals("nsSer", result.getNamespace());
    }

    @Test
    public void testRenameByFieldUsesPrimaryWhenSecondaryEmpty() {
        // For findRenameByField, secondary is higher precedence in the merge call,
        // but since it returns empty values, merge should take primary's non-empty values.
        SimpleAI primary = new SimpleAI(
                null,
                null,
                null,
                null,
                new PropertyName("primaryField", "nsPrimary")
        );
        SimpleAI secondary = new SimpleAI(
                null,
                null,
                null,
                null,
                new PropertyName("", "")
        );

        AnnotationIntrospector pair = AnnotationIntrospectorPair.create(primary, secondary);
        PropertyName result = pair.findRenameByField(null, null, null);

        assertEquals("primaryField", result.getSimpleName());
        assertEquals("nsPrimary", result.getNamespace());
    }

    @Test
    public void testNameForDeserializationMergesPartsFromBoth() {
        // Primary provides simple name only; secondary provides namespace only.
        // Result should combine simple from primary and namespace from secondary.
        SimpleAI primary = new SimpleAI(
                null,
                null,
                null,
                new PropertyName("deserName", null),
                null
        );
        SimpleAI secondary = new SimpleAI(
                null,
                null,
                null,
                new PropertyName("", "nsDeser"),
                null
        );

        AnnotationIntrospector pair = AnnotationIntrospectorPair.create(primary, secondary);
        PropertyName result = pair.findNameForDeserialization(null);

        assertEquals("deserName", result.getSimpleName());
        assertEquals("nsDeser", result.getNamespace());
    }
}

