import java.lang.annotation.Target;
import java.lang.annotation.ElementType;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

public class AnnotationIntrospectorPairMergingTest {

    // Custom trigger annotations for the primary AnnotationIntrospector
    @Retention(RetentionPolicy.RUNTIME)
    @Target({ElementType.FIELD, ElementType.METHOD, ElementType.PARAMETER})
    public @interface PrimaryEmpty { }

    @Retention(RetentionPolicy.RUNTIME)
    @Target({ElementType.FIELD, ElementType.METHOD, ElementType.PARAMETER})
    public @interface PrimaryUseDefault { }

    @Retention(RetentionPolicy.RUNTIME)
    @Target({ElementType.FIELD, ElementType.METHOD, ElementType.PARAMETER})
    public @interface PrimaryName {
        String value() default "";
        String ns() default "";
    }

    // Primary introspector used to simulate XML-like behavior (empty local name/namespace or custom local name)
    static class TestPrimaryIntrospector extends AnnotationIntrospector {
        private static final long serialVersionUID = 1L;

        @Override
        public Version version() {
            return Version.unknownVersion();
        }

        @Override
        public PropertyName findNameForDeserialization(Annotated a) {
            // Return empty simple name and empty namespace if @PrimaryEmpty present
            if (a.hasAnnotation(PrimaryEmpty.class)) {
                return PropertyName.construct("", "");
            }
            // Return USE_DEFAULT if @PrimaryUseDefault present
            if (a.hasAnnotation(PrimaryUseDefault.class)) {
                return PropertyName.USE_DEFAULT;
            }
            // Return specific simple name and namespace if @PrimaryName present
            PrimaryName pn = a.getAnnotation(PrimaryName.class);
            if (pn != null) {
                return PropertyName.construct(pn.value(), pn.ns());
            }
            return null;
        }

        // Implement for symmetry; not required by these tests but harmless
        @Override
        public PropertyName findNameForSerialization(Annotated a) {
            return findNameForDeserialization(a);
        }
    }

    static class POJO1 {
        // Primary introspector provides empty simple/namespace, secondary provides explicit both
        @PrimaryEmpty
        @JsonProperty(namespace = "uri:ns1", value = "prop")
        public int value;
    }

    static class POJO2 {
        // Primary provides simple local name, secondary provides only namespace
        @PrimaryName(value = "local", ns = "")
        @JsonProperty(namespace = "uri:ns2")
        public int x;
    }

    static class POJO3 {
        // Primary signals USE_DEFAULT, secondary provides nothing
        @PrimaryUseDefault
        public int z;
    }

    @Test
    public void testMergeDeserNameFromSecondaryWhenPrimaryEmpty() {
        ObjectMapper mapper = new ObjectMapper();
        AnnotationIntrospector primary = new TestPrimaryIntrospector();
        AnnotationIntrospector secondary = new JacksonAnnotationIntrospector();
        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(primary, secondary);
        mapper.setAnnotationIntrospector(pair);

        DeserializationConfig config = mapper.getDeserializationConfig();
        BeanDescription bd = config.introspect(mapper.getTypeFactory().constructType(POJO1.class));
        List<BeanPropertyDefinition> props = bd.findProperties();

        assertEquals(1, props.size(), "Expected a single property");
        BeanPropertyDefinition def = props.get(0);

        // Validate merged PropertyName (simple name and namespace)
        PropertyName full = def.getFullName();
        assertEquals("prop", full.getSimpleName(), "Merged simple name should come from @JsonProperty");
        assertEquals("uri:ns1", full.getNamespace(), "Merged namespace should come from @JsonProperty");

        // Also directly verify the focal method merge path via AnnotationIntrospectorPair
        PropertyName direct = pair.findNameForDeserialization(def.getPrimaryMember());
        assertNotNull(direct, "Direct merged PropertyName should not be null");
        assertEquals("prop", direct.getSimpleName());
        assertEquals("uri:ns1", direct.getNamespace());
    }

    @Test
    public void testMergeDeserNamePrimaryLocalSecondaryNamespace() {
        ObjectMapper mapper = new ObjectMapper();
        AnnotationIntrospector primary = new TestPrimaryIntrospector();
        AnnotationIntrospector secondary = new JacksonAnnotationIntrospector();
        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(primary, secondary);
        mapper.setAnnotationIntrospector(pair);

        DeserializationConfig config = mapper.getDeserializationConfig();
        BeanDescription bd = config.introspect(mapper.getTypeFactory().constructType(POJO2.class));
        List<BeanPropertyDefinition> props = bd.findProperties();

        assertEquals(1, props.size(), "Expected a single property");
        BeanPropertyDefinition def = props.get(0);

        // Expected: simple from primary ("local"), namespace from secondary ("uri:ns2")
        PropertyName full = def.getFullName();
        assertEquals("local", full.getSimpleName(), "Simple name should come from primary introspector");
        assertEquals("uri:ns2", full.getNamespace(), "Namespace should come from secondary introspector");

        // Verify via direct invocation of the focal method
        PropertyName direct = pair.findNameForDeserialization(def.getPrimaryMember());
        assertNotNull(direct);
        assertEquals("local", direct.getSimpleName());
        assertEquals("uri:ns2", direct.getNamespace());
    }

    @Test
    public void testMergeReturnsUseDefaultWhenSecondaryNull() {
        ObjectMapper mapper = new ObjectMapper();
        AnnotationIntrospector primary = new TestPrimaryIntrospector();
        // Secondary returns null (no @JsonProperty on the member)
        AnnotationIntrospector secondary = new JacksonAnnotationIntrospector();
        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(primary, secondary);
        mapper.setAnnotationIntrospector(pair);

        DeserializationConfig config = mapper.getDeserializationConfig();
        BeanDescription bd = config.introspect(mapper.getTypeFactory().constructType(POJO3.class));
        List<BeanPropertyDefinition> props = bd.findProperties();

        assertEquals(1, props.size(), "Expected a single property");
        BeanPropertyDefinition def = props.get(0);

        // Directly call focal method: primary -> USE_DEFAULT, secondary -> null
        PropertyName merged = pair.findNameForDeserialization(def.getPrimaryMember());
        assertSame(PropertyName.USE_DEFAULT, merged,
                "Merged PropertyName should be USE_DEFAULT when primary is USE_DEFAULT and secondary is null");
    }
}

