package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

import static org.junit.jupiter.api.Assertions.*;

public class Issue4229ObjectNodeFindValuesParentsTest {

    private static final ObjectMapper MAPPER = new ObjectMapper();

    private ObjectNode buildSampleTree() {
        ObjectNode root = MAPPER.createObjectNode();

        root.put("target", "root");

        ObjectNode a = root.putObject("a");
        a.put("target", "a1");
        ObjectNode nested = a.putObject("nested");
        nested.put("target", "a2");

        ObjectNode b = root.putObject("b");
        b.put("other", 123);
        b.put("target", "b1");

        ArrayNode array = root.putArray("array");
        ObjectNode arr0 = array.addObject();
        arr0.put("target", "arr1");
        ObjectNode arr1 = array.addObject();
        ObjectNode arr1x = arr1.putObject("x");
        arr1x.put("target", "arr2");

        return root;
    }

    @Test
    public void testFindValuesAsTextCollectsAllMatchesInDocumentOrder() throws Exception {
        ObjectNode root = buildSampleTree();

        List<String> valuesAsText = root.findValuesAsText("target");

        // Expect all occurrences in document order
        List<String> expected = Arrays.asList("root", "a1", "a2", "b1", "arr1", "arr2");
        assertEquals(expected, valuesAsText, "findValuesAsText should collect all matches in document order");
    }

    @Test
    public void testFindValuesCollectsAllMatchesInDocumentOrder() throws Exception {
        ObjectNode root = buildSampleTree();

        List<JsonNode> values = root.findValues("target");
        List<String> texts = values.stream().map(JsonNode::asText)
                .collect(Collectors.toList());

        List<String> expected = Arrays.asList("root", "a1", "a2", "b1", "arr1", "arr2");
        assertEquals(6, values.size(), "findValues should return all 6 matching nodes");
        assertEquals(expected, texts, "findValues should return values in document order");
    }

    @Test
    public void testFindParentsCollectsAllParentsInDocumentOrder() throws Exception {
        ObjectNode root = MAPPER.createObjectNode();

        root.put("target", "root");

        ObjectNode aNode = root.putObject("a");
        aNode.put("target", "a1");
        ObjectNode nestedNode = aNode.putObject("nested");
