package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.deser.std.StdNodeBasedDeserializer;
import com.fasterxml.jackson.databind.module.SimpleModule;
import com.fasterxml.jackson.databind.node.JsonNodeFactory;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.fasterxml.jackson.databind.type.TypeFactory;
import org.junit.Assert;
import org.junit.Test;

import java.io.IOException;

public class StdNodeBasedDeserializerUpdatingTest {

    // Simple bean for updating-deserializer test
    public static class UpdatableBean {
        public int a;
        public String b;

        public UpdatableBean() { }

        public UpdatableBean(int a, String b) {
            this.a = a;
            this.b = b;
        }
    }

    // Deserializer that properly overrides convert(JsonNode, DeserializationContext, T)
    static class UpdatableBeanDeserializer extends StdNodeBasedDeserializer<UpdatableBean> {
        private static final long serialVersionUID = 1L;

        protected UpdatableBeanDeserializer() {
            super(TypeFactory.defaultInstance().constructType(UpdatableBean.class));
        }

        @Override
        public UpdatableBean convert(JsonNode root, DeserializationContext ctxt) throws IOException {
            // For non-updating flow, construct a new instance from the node
            UpdatableBean bean = new UpdatableBean();
            if (root.has("a")) {
                bean.a = root.get("a").asInt();
            }
            if (root.has("b")) {
                bean.b = root.get("b").asText();
            }
            return bean;
        }

        @Override
        public UpdatableBean convert(JsonNode root, DeserializationContext ctxt, UpdatableBean newValue) throws IOException {
            // Update existing instance based on node
            if (root.has("a")) {
                newValue.a = root.get("a").asInt();
            }
            if (root.has("b")) {
                newValue.b = root.get("b").asText();
            }
            return newValue;
        }
    }

    // Second bean and deserializer for default (non-overridden) convert(T) behavior
    public static class NonMergingBean {
        public int x;
        public String y;

        public NonMergingBean() { }

        public NonMergingBean(int x, String y) {
            this.x = x;
            this.y = y;
        }
    }

    // Deserializer that does NOT override convert(JsonNode, DeserializationContext, T)
    // so that default implementation (handleBadMerge + fallback) is used.
    static class NonMergingBeanDeserializer extends StdNodeBasedDeserializer<NonMergingBean> {
        private static final long serialVersionUID = 1L;

        protected NonMergingBeanDeserializer() {
            super(TypeFactory.defaultInstance().constructType(NonMergingBean.class));
        }

        @Override
        public NonMergingBean convert(JsonNode root, DeserializationContext ctxt) throws IOException {
            NonMergingBean bean = new NonMergingBean();
            if (root.has("x")) {
                bean.x = root.get("x").asInt();
            }
            if (root.has("y")) {
                bean.y = root.get("y").asText();
            }
            return bean;
        }
    }

    @Test
    public void testReaderForUpdatingUsesNodeBasedConvertWithExistingValue() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        SimpleModule m = new SimpleModule();
        m.addDeserializer(UpdatableBean.class, new UpdatableBeanDeserializer());
        mapper.registerModule(m);

        UpdatableBean existing = new UpdatableBean(1, "orig");

        // Only "a" is provided; expect "b" to remain unchanged after update
        String json = "{ \"a\": 7 }";

        // Use readerForUpdating: should invoke StdNodeBasedDeserializer.deserialize(jp, ctxt, newValue)
        UpdatableBean result = mapper.readerForUpdating(existing).readValue(json);

        // Must be the same instance (updated in place)
        Assert.assertSame(existing, result);
        // "a" updated from JSON; "b" preserved
        Assert.assertEquals(7, result.a);
        Assert.assertEquals("orig", result.b);
    }

    @Test
    public void testDefaultConvertIgnoresExistingValueAndFallsBackToNonUpdating() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        // Ensure that a "bad merge" does not fail the test: ignore merge complaints for unmergeable types
        mapper.enable(MapperFeature.IGNORE_MERGE_FOR_UNMERGEABLE);

        SimpleModule m = new SimpleModule();
        m.addDeserializer(NonMergingBean.class, new NonMergingBeanDeserializer());
        mapper.registerModule(m);

        NonMergingBean existing = new NonMergingBean(10, "keep");
        String json = "{ \"x\": 123, \"y\": \"new\" }";

        // Since NonMergingBeanDeserializer does not override convert(..., T),
        // default implementation should be used: it calls handleBadMerge and then falls back to convert(root, ctxt),
        // which creates a new instance, effectively ignoring the existing value.
        NonMergingBean result = mapper.readerForUpdating(existing).readValue(json);

        // Should NOT be the same instance since existing value was ignored
        Assert.assertNotSame(existing, result);
        // Existing object remains unchanged
        Assert.assertEquals(10, existing.x);
        Assert.assertEquals("keep", existing.y);
        // Result reflects JSON content via non-updating convert(root, ctxt)
        Assert.assertEquals(123, result.x);
        Assert.assertEquals("new", result.y);
    }
}

