package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.annotation.JsonInclude;
import com.fasterxml.jackson.core.JsonFactory;
import org.junit.Test;

import static org.junit.Assert.*;

public class ObjectMapperCopyWithTest {

    @Test
    public void testCopyWithUsesProvidedFactoryAndCopiesConfig() {
        // Given a pre-configured ObjectMapper
        ObjectMapper original = new ObjectMapper();
        original.setSerializationInclusion(JsonInclude.Include.NON_NULL);
        original.enable(SerializationFeature.INDENT_OUTPUT);
        original.setPropertyNamingStrategy(PropertyNamingStrategy.SNAKE_CASE);

        JsonFactory originalFactory = original.getFactory();
        assertSame("Original factory should be bound to original mapper", original, originalFactory.getCodec());

        // And a different JsonFactory
        JsonFactory newFactory = new JsonFactory();
        assertNotSame("Precondition: newFactory should be a different instance", originalFactory, newFactory);

        // When copying with the provided factory
        ObjectMapper copy = original.copyWith(newFactory);

        // Then the copy should be a different mapper instance
        assertNotSame("copyWith must return a new ObjectMapper instance", original, copy);

        // And it must use exactly the provided JsonFactory instance
        assertSame("copyWith must use the provided JsonFactory instance", newFactory, copy.getFactory());

        // And the provided factory must be bound to the new mapper as codec
        assertSame("Provided factory should be rebound to the new mapper", copy, newFactory.getCodec());

        // And the original mapper's factory remains intact and bound to the original mapper
        assertSame("Original mapper's factory should stay the same", originalFactory, original.getFactory());
        assertSame("Original factory should remain bound to original mapper", original, original.getFactory().getCodec());

        // And configuration must be faithfully copied
        assertTrue("SerializationFeature.INDENT_OUTPUT should be enabled on the copy",
                copy.getSerializationConfig().isEnabled(SerializationFeature.INDENT_OUTPUT));
        assertEquals(
                "Default property inclusion must be copied",
                original.getSerializationConfig().getDefaultPropertyInclusion(),
                copy.getSerializationConfig().getDefaultPropertyInclusion()
        );
        assertSame(
                "PropertyNamingStrategy must be copied",
                original.getPropertyNamingStrategy(),
                copy.getPropertyNamingStrategy()
        );
    }

    @Test
    public void testIndependenceBetweenOriginalAndCopyWith() {
        // Given a mapper with a specific configuration
        ObjectMapper original = new ObjectMapper();
        original.setSerializationInclusion(JsonInclude.Include.NON_NULL);
        original.enable(SerializationFeature.INDENT_OUTPUT);

        // When creating a copy with a different factory
        JsonFactory newFactory = new JsonFactory();
        ObjectMapper copy = original.copyWith(newFactory);

        // Precondition checks
        assertTrue(original.getSerializationConfig().isEnabled(SerializationFeature.INDENT_OUTPUT));
        assertTrue(copy.getSerializationConfig().isEnabled(SerializationFeature.INDENT_OUTPUT));

        // Changing copy's config should not affect original
        copy.disable(SerializationFeature.INDENT_OUTPUT);
        assertFalse("Copy should reflect its own config changes",
                copy.getSerializationConfig().isEnabled(SerializationFeature.INDENT_OUTPUT));
        assertTrue("Original should not be affected by copy's changes",
                original.getSerializationConfig().isEnabled(SerializationFeature.INDENT_OUTPUT));

        // Changing original's inclusion should not affect copy
        original.setSerializationInclusion(JsonInclude.Include.ALWAYS);
        assertEquals("Original should reflect its inclusion change",
                JsonInclude.Include.ALWAYS,
                original.getSerializationConfig().getDefaultPropertyInclusion().getValueInclusion());
        assertEquals("Copy should retain its original inclusion setting (independent from original)",
                JsonInclude.Include.NON_NULL,
                copy.getSerializationConfig().getDefaultPropertyInclusion().getValueInclusion());
    }
}

