package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.JsonAnySetter;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;

import java.util.AbstractMap;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;

import static org.junit.Assert.*;

public class AnySetterNullMapInitializationTest {

    // Bean with raw Map field annotated as any-setter; field left null initially
    static class BeanWithRawMapAny {
        @JsonAnySetter
        public Map<String, String> other;
    }

    // Bean with HashMap field annotated as any-setter; field left null initially
    static class BeanWithHashMapAny {
        @JsonAnySetter
        public HashMap<String, String> stuff;
    }

    // Custom non-JDK Map type to trigger instantiator-absence path
    static class WeirdMap extends AbstractMap<String, String> {
        @Override
        public Set<Map.Entry<String, String>> entrySet() {
            return Collections.emptySet();
        }
    }

    // Bean with unsupported Map implementation for any-setter
    static class BeanWithWeirdMapAny {
        @JsonAnySetter
        public WeirdMap other;
    }

    private final ObjectMapper MAPPER = new ObjectMapper();

    @Test
    public void testNullRawMapAnySetterGetsInitializedWithLinkedHashMap() throws Exception {
        BeanWithRawMapAny result = MAPPER.readValue("{\"a\":\"b\"}", BeanWithRawMapAny.class);

        assertNotNull("Map field should be initialized", result.other);
        assertTrue("Map should be a LinkedHashMap when field type is raw Map",
                result.other instanceof LinkedHashMap);
        assertEquals("b", result.other.get("a"));
        assertEquals(1, result.other.size());
    }

    @Test
    public void testNullHashMapAnySetterGetsInitialized() throws Exception {
        BeanWithHashMapAny result = MAPPER.readValue("{\"k\":\"v\"}", BeanWithHashMapAny.class);

        assertNotNull("Map field should be initialized", result.stuff);
        assertTrue("Map should be a HashMap when field type is HashMap",
                result.stuff instanceof HashMap);
        assertEquals("v", result.stuff.get("k"));
        assertEquals(1, result.stuff.size());
    }

    @Test
    public void testUnsupportedMapAnySetterThrowsMeaningfulException() {
        try {
            MAPPER.readValue("{\"x\":\"y\"}", BeanWithWeirdMapAny.class);
            fail("Expected JsonMappingException due to unsupported Map type for @JsonAnySetter");
        } catch (JsonMappingException e) {
            String msg = e.getMessage();
            assertNotNull(msg);
            // Ensure the message is clear and references any-setter and the field name
            assertTrue("Error message should mention inability to create instance",
                    msg.contains("Cannot create an instance of"));
            assertTrue("Error message should mention any-setter", msg.contains("any-setter"));
            assertTrue("Error message should mention the property name",
                    msg.contains("'other'"));
        } catch (Exception e) {
            fail("Expected JsonMappingException, got: " + e);
        }
    }
}

