package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.cfg.CoercionAction;
import com.fasterxml.jackson.databind.cfg.CoercionInputShape;
import com.fasterxml.jackson.databind.exc.MismatchedInputException;
import com.fasterxml.jackson.databind.type.LogicalType;
import org.junit.Test;

import java.math.BigDecimal;

import static org.junit.Assert.*;

public class IntToFloatCoercionTest {

    @Test
    public void testIntegerToDoubleWrapperFailConfigured() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.Fail);

        try {
            mapper.readValue("11", Double.class);
            fail("Should have failed with MismatchedInputException due to Integer->Float coercion set to Fail");
        } catch (MismatchedInputException e) {
            // expected; ensure it's the right type of failure
            assertTrue(e.getMessage() == null || e.getMessage().contains("Integer"));
        }
    }

    @Test
    public void testIntegerToBigDecimalFailConfigured() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.Fail);

        try {
            mapper.readValue("11", BigDecimal.class);
            fail("Should have failed with MismatchedInputException due to Integer->Float(BigDecimal) coercion set to Fail");
        } catch (MismatchedInputException e) {
            // expected failure
            assertTrue(e.getMessage() == null || e.getMessage().contains("Integer"));
        }
    }

    @Test
    public void testIntegerToFloatPrimitiveAsNullReturnsZero() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.AsNull);

        float value = mapper.readValue("11", Float.TYPE);
        assertEquals(0.0f, value, 0.0f);
    }

    @Test
    public void testIntegerToDoublePrimitiveAsEmptyReturnsZero() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.AsEmpty);

        double value = mapper.readValue("11", Double.TYPE);
        assertEquals(0.0d, value, 0.0d);
    }

    @Test
    public void testIntegerToFloatWrapperAsNullReturnsNull() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.AsNull);

        Float value = mapper.readValue("11", Float.class);
        assertNull(value);
    }

    @Test
    public void testDefaultAllowsIntegerToDoubleCoercion() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        // No special coercion config; default should allow coercion
        Double value = mapper.readValue("11", Double.class);
        assertNotNull(value);
        assertEquals(11.0d, value, 0.0d);
    }
}

