package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.annotation.JsonSetter;
import com.fasterxml.jackson.annotation.Nulls;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.annotation.JsonDeserialize;
import com.fasterxml.jackson.databind.annotation.JsonPOJOBuilder;
import org.junit.Test;

import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.*;

public class NullsSkipOnSetMethodsTest {

    // Simple inner POJO used for list element type
    static class Inner {
        public String field1;
    }

    // ====== Scenario 1: FieldProperty via public field ======

    static class OuterField {
        public List<MiddleField> list1;
    }

    static class MiddleField {
        // Initialized to non-null, and must not be overwritten by null
        @JsonSetter(nulls = Nulls.SKIP)
        public List<Inner> list1 = new ArrayList<>();

        public String field1;

        public List<Inner> getList1() {
            return list1;
        }
    }

    // ====== Scenario 2: MethodProperty via setter method ======

    static class OuterMethod {
        public List<MiddleMethod> list1;
    }

    static class MiddleMethod {
        private List<Inner> list1 = new ArrayList<>();
        public String field1;

        public List<Inner> getList1() {
            return list1;
        }

        @JsonSetter(nulls = Nulls.SKIP)
        public void setList1(List<Inner> list1) {
            this.list1 = list1;
        }
    }

    // ====== Scenario 3: Builder-based (MethodProperty.setAndReturn path) ======

    @JsonDeserialize(builder = BeanBuiltByMethodBuilder.Builder.class)
    static class BeanBuiltByMethodBuilder {
        private final List<Inner> list1;

        private BeanBuiltByMethodBuilder(List<Inner> list1) {
            this.list1 = list1;
        }

        public List<Inner> getList1() {
            return list1;
        }

        @JsonPOJOBuilder(withPrefix = "")
        public static class Builder {
            List<Inner> list1 = new ArrayList<>();

            @JsonSetter(nulls = Nulls.SKIP)
            public Builder list1(List<Inner> v) {
                this.list1 = v;
                return this;
            }

            public BeanBuiltByMethodBuilder build() {
                return new BeanBuiltByMethodBuilder(list1);
            }
        }
    }

    // ====== Scenario 4: Builder-based using public field (FieldProperty.setAndReturn path) ======

    @JsonDeserialize(builder = BeanBuiltByFieldBuilder.Builder.class)
    static class BeanBuiltByFieldBuilder {
        private final List<Inner> list1;

        private BeanBuiltByFieldBuilder(List<Inner> list1) {
            this.list1 = list1;
        }

        public List<Inner> getList1() {
            return list1;
        }

        @JsonPOJOBuilder(withPrefix = "")
        public static class Builder {
            @JsonSetter(nulls = Nulls.SKIP)
            public List<Inner> list1 = new ArrayList<>();

            public BeanBuiltByFieldBuilder build() {
                return new BeanBuiltByFieldBuilder(list1);
            }
        }
    }

    @Test
    public void testNullSkipOnFieldPropertyWithinNestedStructure() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{ \"list1\": [ { \"list1\": null, \"field1\": \"data\" } ] }";

        OuterField outer = mapper.readValue(json, OuterField.class);
        assertNotNull("Outer.list1 should not be null", outer.list1);
        assertEquals("Outer.list1 size", 1, outer.list1.size());

        MiddleField middle = outer.list1.get(0);
        assertNotNull("MiddleField.getList1() should not be null when nulls are skipped", middle.getList1());
        assertTrue("MiddleField.getList1() should be the initialized empty list", middle.getList1().isEmpty());
    }

    @Test
    public void testNullSkipOnMethodPropertyWithinNestedStructure() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{ \"list1\": [ { \"list1\": null, \"field1\": \"data\" } ] }";

        OuterMethod outer = mapper.readValue(json, OuterMethod.class);
        assertNotNull("Outer.list1 should not be null", outer.list1);
        assertEquals("Outer.list1 size", 1, outer.list1.size());

        MiddleMethod middle = outer.list1.get(0);
        assertNotNull("MiddleMethod.getList1() should not be null when nulls are skipped", middle.getList1());
        assertTrue("MiddleMethod.getList1() should be the initialized empty list", middle.getList1().isEmpty());
    }

    @Test
    public void testNullSkipOnBuilderMethodPropertySetAndReturnPath() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{ \"list1\": null }";
        BeanBuiltByMethodBuilder result = mapper.readValue(json, BeanBuiltByMethodBuilder.class);

        assertNotNull("Builder-method-based bean list1 should not be null when nulls are skipped", result.getList1());
        assertTrue("Builder-method-based bean list1 should be the initialized empty list", result.getList1().isEmpty());
    }

    @Test
    public void testNullSkipOnBuilderFieldPropertySetAndReturnPath() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{ \"list1\": null }";
        BeanBuiltByFieldBuilder result = mapper.readValue(json, BeanBuiltByFieldBuilder.class);

        assertNotNull("Builder-field-based bean list1 should not be null when nulls are skipped", result.getList1());
        assertTrue("Builder-field-based bean list1 should be the initialized empty list", result.getList1().isEmpty());
    }
}

