package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.annotation.JsonSubTypes;
import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Assert;
import org.junit.Test;

public class ExternalTypeIdWithIgnorePropertiesTest {

    // Parent has a property annotated with @JsonIgnoreProperties
    static class Parent {
        @JsonIgnoreProperties(value = { "ignored" })
        public Child child;
    }

    // Child contains a polymorphic field using EXTERNAL_PROPERTY type info
    static class Child {
        @JsonTypeInfo(use = JsonTypeInfo.Id.NAME,
                include = JsonTypeInfo.As.EXTERNAL_PROPERTY,
                property = "childType")
        @JsonSubTypes({
                @JsonSubTypes.Type(value = SubChildA.class, name = "A")
        })
        public SubChild subChild;
    }

    interface SubChild { }

    static class SubChildA implements SubChild {
        // no fields needed
        public SubChildA() { }
    }

    @Test
    public void testExternalTypeIdAndIgnorePropertiesInteroperability() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // "ignored" should be ignored due to @JsonIgnoreProperties on Parent.child
        // "childType" is the external type id for "subChild"
        String json = "{\"child\":{\"ignored\":13,\"childType\":\"A\",\"subChild\":{}}}";

        Parent p = mapper.readValue(json, Parent.class);

        Assert.assertNotNull("Parent should not be null", p);
        Assert.assertNotNull("Child should not be null", p.child);
        Assert.assertNotNull("subChild should not be null", p.child.subChild);
        Assert.assertTrue("subChild should be resolved as SubChildA when using EXTERNAL_PROPERTY",
                p.child.subChild instanceof SubChildA);
    }
}

