package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.JsonCreator;
import com.fasterxml.jackson.annotation.JsonSetter;
import com.fasterxml.jackson.annotation.Nulls;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.exc.InvalidNullException;
import org.junit.Test;

import java.util.Map;

import static org.junit.Assert.*;

/**
 * Tests for issue #4200:
 * {@code @JsonSetter(contentNulls = Nulls.FAIL)} must be honored for delegating
 * {@code @JsonCreator} parameters.
 *
 * Also covers config-override based setter info resolution used by the new
 * BeanDeserializerBase._getSetterInfo() helper.
 */
public class DelegatingCreatorContentNullsFailTest {

    public static class AnnotatedDelegatingWrapper {
        public final Map<String, String> values;

        @JsonCreator(mode = JsonCreator.Mode.DELEGATING)
        public AnnotatedDelegatingWrapper(
                @JsonSetter(contentNulls = Nulls.FAIL) Map<String, String> values) {
            this.values = values;
        }
    }

    public static class UnannotatedDelegatingWrapper {
        public final Map<String, String> values;

        @JsonCreator(mode = JsonCreator.Mode.DELEGATING)
        public UnannotatedDelegatingWrapper(Map<String, String> values) {
            this.values = values;
        }
    }

    @Test
    public void annotatedDelegatingCreatorFailsOnNullMapContent() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        try {
            mapper.readValue("{\"foo\":null}", AnnotatedDelegatingWrapper.class);
            fail("Expected InvalidNullException for null Map content");
        } catch (InvalidNullException e) {
            // Expected: annotation on delegating creator parameter must be honored
        }
    }

    @Test
    public void annotatedDelegatingCreatorStillAcceptsValidMapContent() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        AnnotatedDelegatingWrapper result = mapper.readValue("{\"a\":\"b\"}", AnnotatedDelegatingWrapper.class);
        assertNotNull(result);
        assertNotNull(result.values);
        assertEquals(1, result.values.size());
        assertEquals("b", result.values.get("a"));
    }

    @Test
    public void configOverrideAppliesToDelegatingCreatorParameter() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.configOverride(Map.class)
                .setSetterInfo(JsonSetter.Value.construct(Nulls.FAIL, Nulls.FAIL));

        try {
            mapper.readValue("{\"foo\":null}", UnannotatedDelegatingWrapper.class);
            fail("Expected InvalidNullException for null Map content from config override");
        } catch (InvalidNullException e) {
            // Expected: config override should be consulted for delegating creator parameters too
        }
    }
}

