package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.annotation.JsonRootName;
import com.fasterxml.jackson.databind.node.JsonNodeFactory;
import com.fasterxml.jackson.databind.node.JsonNodeType;
import com.fasterxml.jackson.databind.JsonNode;
import org.junit.Assert;
import org.junit.Test;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.Map;

public class ValueToTreeWrapRootTest {

    @JsonRootName("event")
    static class Event {
        public Long id;
        public String name;

        Event() { }

        Event(Long id, String name) {
            this.id = id;
            this.name = name;
        }
    }

    @Test
    public void testValueToTreeNullReturnsNullNode() {
        ObjectMapper mapper = new ObjectMapper();

        JsonNode result = mapper.valueToTree(null);

        Assert.assertTrue(result.isNull());
        Assert.assertEquals(JsonNodeType.NULL, result.getNodeType());
    }

    @Test
    public void testValueToTreeHonorsWrapRootValue() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(SerializationFeature.WRAP_ROOT_VALUE);

        Event event = new Event(1L, "test");

        JsonNode result = mapper.valueToTree(event);

        Assert.assertTrue("Result should be an object node", result.isObject());
        Assert.assertTrue("Root should contain 'event' wrapper field", result.has("event"));

        JsonNode wrapped = result.get("event");
        Assert.assertTrue("Wrapped value should be an object", wrapped.isObject());
        Assert.assertEquals(1L, wrapped.get("id").asLong());
        Assert.assertEquals("test", wrapped.get("name").asText());

        // valueToTree() should be consistent with writeValueAsString() when root wrapping is enabled
        String expectedJson = mapper.writeValueAsString(event);
        Assert.assertEquals("{\"event\":{\"id\":1,\"name\":\"test\"}}", expectedJson);
        Assert.assertEquals(expectedJson, result.toString());
    }

    @Test
    public void testValueToTreeWithoutWrapRootValue() {
        ObjectMapper mapper = new ObjectMapper();
        mapper.disable(SerializationFeature.WRAP_ROOT_VALUE);

        Event event = new Event(2L, "plain");

        JsonNode result = mapper.valueToTree(event);

        Assert.assertTrue("Result should be an object node", result.isObject());
        Assert.assertFalse("There should be no 'event' wrapper field when WRAP_ROOT_VALUE is disabled", result.has("event"));

        Assert.assertEquals(2L, result.get("id").asLong());
        Assert.assertEquals("plain", result.get("name").asText());
        Assert.assertEquals("{\"id\":2,\"name\":\"plain\"}", result.toString());
    }

    @Test
    public void testValueToTreeUsesBigDecimalWhenConfigured() {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS);

        Map<String, Object> input = new LinkedHashMap<String, Object>();
        input.put("value", 1.25d);

        JsonNode result = mapper.valueToTree(input);

        Assert.assertTrue(result.isObject());
        Assert.assertTrue(result.get("value").isBigDecimal());
        Assert.assertEquals(new BigDecimal("1.25"), result.get("value").decimalValue());
    }
}

