package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.annotation.JsonIgnore;
import com.fasterxml.jackson.databind.MapperFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class Issue3948Test
{
    /**
     * Regression test for databind#3948:
     * a transient field annotated with @JsonIgnore must still be ignored even when
     * MapperFeature.PROPAGATE_TRANSIENT_MARKER is disabled (default).
     */
    static class BeanWithTransientIgnoredField {
        public String visible = "visible-value";

        @JsonIgnore
        private transient String hidden;

        public BeanWithTransientIgnoredField() { }

        public BeanWithTransientIgnoredField(String visible, String hidden) {
            this.visible = visible;
            this.hidden = hidden;
        }

        public String getHidden() {
            return hidden;
        }

        public void setHidden(String hidden) {
            this.hidden = hidden;
        }
    }

    /**
     * Coverage helper: transient field without @JsonIgnore should only be suppressed
     * when PROPAGATE_TRANSIENT_MARKER is enabled.
     */
    static class BeanWithTransientField {
        public String visible = "visible-value";

        private transient String hidden;

        public BeanWithTransientField() { }

        public BeanWithTransientField(String visible, String hidden) {
            this.visible = visible;
            this.hidden = hidden;
        }

        public String getHidden() {
            return hidden;
        }

        public void setHidden(String hidden) {
            this.hidden = hidden;
        }
    }

    @Test
    public void testJsonIgnoreOnTransientFieldIsRespectedByDefault() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        BeanWithTransientIgnoredField input = new BeanWithTransientIgnoredField("visible-value", "secret-value");
        String json = mapper.writeValueAsString(input);

        // The transient + @JsonIgnore field must not be serialized
        assertEquals("{\"visible\":\"visible-value\"}", json);
        assertFalse(json.contains("hidden"));
        assertFalse(json.contains("secret-value"));

        // And it must not be deserialized
        BeanWithTransientIgnoredField output = mapper.readValue(
                "{\"visible\":\"changed\",\"hidden\":\"secret-value\"}",
                BeanWithTransientIgnoredField.class);

        assertEquals("changed", output.visible);
        assertNull(output.getHidden());
    }

    @Test
    public void testJsonIgnoreOnTransientFieldIsRespectedWithPropagateTransientMarkerEnabled() throws Exception {
        ObjectMapper mapper = new ObjectMapper()
                .enable(MapperFeature.PROPAGATE_TRANSIENT_MARKER);

        BeanWithTransientIgnoredField input = new BeanWithTransientIgnoredField("visible-value", "secret-value");
        String json = mapper.writeValueAsString(input);

        // Behavior should remain the same even when transient markers are propagated
        assertEquals("{\"visible\":\"visible-value\"}", json);
        assertFalse(json.contains("hidden"));
        assertFalse(json.contains("secret-value"));

        BeanWithTransientIgnoredField output = mapper.readValue(
                "{\"visible\":\"changed\",\"hidden\":\"secret-value\"}",
                BeanWithTransientIgnoredField.class);

        assertEquals("changed", output.visible);
        assertNull(output.getHidden());
    }

    @Test
    public void testTransientFieldWithoutJsonIgnoreIsOnlyIgnoredWhenPropagationEnabled() throws Exception {
        BeanWithTransientField input = new BeanWithTransientField("visible-value", "secret-value");

        ObjectMapper defaultMapper = new ObjectMapper();
        String defaultJson = defaultMapper.writeValueAsString(input);

        // By default, transient does not suppress accessor-backed properties
        assertTrue(defaultJson.contains("\"visible\":\"visible-value\""));
        assertTrue(defaultJson.contains("\"hidden\":\"secret-value\""));

        ObjectMapper propagatedMapper = new ObjectMapper()
                .enable(MapperFeature.PROPAGATE_TRANSIENT_MARKER);
        String propagatedJson = propagatedMapper.writeValueAsString(input);

        // With propagation enabled, the transient property should be suppressed
        assertTrue(propagatedJson.contains("\"visible\":\"visible-value\""));
        assertFalse(propagatedJson.contains("hidden"));
        assertFalse(propagatedJson.contains("secret-value"));
    }
}

