package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.JsonAnySetter;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializerProvider;
import org.junit.Test;

import java.util.AbstractMap;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;

import static org.junit.Assert.*;

public class SettableAnyPropertyNullMapInitTest {

    public static class BeanWithRawMapAny {
        @JsonAnySetter
        public Map<String, String> other;
    }

    public static class BeanWithHashMapAny {
        @JsonAnySetter
        public HashMap<String, String> other;
    }

    // A custom Map type that is not supported by JDKValueInstantiators
    public static class UnsupportedMap<K, V> extends AbstractMap<K, V> {
        @Override
        public Set<Entry<K, V>> entrySet() {
            return new java.util.HashSet<Entry<K, V>>();
        }
    }

    public static class BeanWithUnsupportedMapAny {
        @JsonAnySetter
        public UnsupportedMap<String, String> other;
    }

    @Test
    public void testAnySetterInitializesRawMap() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        BeanWithRawMapAny bean = mapper.readValue("{\"x\":\"1\",\"y\":\"2\"}", BeanWithRawMapAny.class);

        assertNotNull("Map field should be initialized", bean.other);
        assertTrue("Default Map type should be LinkedHashMap for raw Map",
                bean.other instanceof LinkedHashMap);
        assertEquals("1", bean.other.get("x"));
        assertEquals("2", bean.other.get("y"));
    }

    @Test
    public void testAnySetterInitializesConcreteHashMap() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        BeanWithHashMapAny bean = mapper.readValue("{\"a\":\"b\"}", BeanWithHashMapAny.class);

        assertNotNull("HashMap field should be initialized", bean.other);
        assertTrue("Expected HashMap to be created for concrete HashMap field",
                bean.other instanceof HashMap);
        assertEquals("b", bean.other.get("a"));
    }

    @Test
    public void testAnySetterUnsupportedMapTypeThrowsClearMessage() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        try {
            mapper.readValue("{\"x\":\"1\"}", BeanWithUnsupportedMapAny.class);
            fail("Expected JsonMappingException due to unsupported Map type for any-setter");
        } catch (JsonMappingException e) {
            String msg = e.getMessage();
            assertNotNull(msg);

            // Be tolerant about exact wording, but verify the essential details.
            assertTrue("Error message should indicate instantiation failure: " + msg,
                    msg.contains("Cannot create an instance") || msg.contains("Cannot construct instance"));
            assertTrue("Error message should mention any-setter / any-property: " + msg,
                    msg.contains("any-setter") || msg.contains("any-property"));
            assertTrue("Error message should include property name: " + msg,
                    msg.contains("other"));
        }
    }

    @Test
    public void testJsonMappingExceptionFromNullSerializerProviderDoesNotNPE() {
        JsonMappingException ex = JsonMappingException.from((SerializerProvider) null, "hello");
        assertNotNull(ex);
        assertNull("Processor should be null when SerializerProvider is null", ex.getProcessor());
        assertTrue("Message should be preserved", ex.getMessage().contains("hello"));
    }

    @Test
    public void testJsonMappingExceptionFromNullDeserializationContextDoesNotNPE() {
        JsonMappingException ex = JsonMappingException.from((DeserializationContext) null, "world");
        assertNotNull(ex);
        assertNull("Processor should be null when DeserializationContext is null", ex.getProcessor());
        assertTrue("Message should be preserved", ex.getMessage().contains("world"));
    }
}

