package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.annotation.JsonDeserialize;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.io.IOException;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests for databind#4184:
 * BeanDeserializer.vanillaDeserialize() must only set parser currentValue
 * when deserializing a non-empty Object.
 */
public class BeanDeserializerCurrentValue4184Test {

    public static class EmptyBean {
        // intentionally empty
    }

    public static class ChildBean {
        @JsonDeserialize(using = CurrentValueCapturingStringDeserializer.class)
        public String value;
    }

    public static class ParentWithEmptyChild {
        public EmptyBean empty;

        @JsonDeserialize(using = CurrentValueCapturingStringDeserializer.class)
        public String sibling;
    }

    public static class ParentWithNonEmptyChild {
        public ChildBean child;
    }

    /**
     * Captures JsonParser.getCurrentValue() at the point a String property is deserialized.
     */
    public static class CurrentValueCapturingStringDeserializer extends JsonDeserializer<String> {
        static Object lastCurrentValue;

        @Override
        public String deserialize(JsonParser p, DeserializationContext ctxt) throws IOException {
            lastCurrentValue = p.getCurrentValue();
            return p.getValueAsString();
        }
    }

    @BeforeEach
    public void resetCapture() {
        CurrentValueCapturingStringDeserializer.lastCurrentValue = null;
    }

    @Test
    public void emptyObjectDoesNotOverrideCurrentValueForFollowingSiblingProperty() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        ParentWithEmptyChild result = mapper.readValue(
                "{\"empty\":{},\"sibling\":\"ok\"}",
                ParentWithEmptyChild.class
        );

        assertNotNull(result);
        assertNotNull(result.empty);
        assertEquals("ok", result.sibling);

        assertSame(result, CurrentValueCapturingStringDeserializer.lastCurrentValue,
                "Sibling property deserializer must see the parent bean as currentValue");
        assertNotSame(result.empty, CurrentValueCapturingStringDeserializer.lastCurrentValue,
                "Empty child bean must not replace parser currentValue");
    }

    @Test
    public void nonEmptyObjectSetsCurrentValueForNestedPropertyDeserialization() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        ParentWithNonEmptyChild result = mapper.readValue(
                "{\"child\":{\"value\":\"A\"}}",
                ParentWithNonEmptyChild.class
        );

        assertNotNull(result);
        assertNotNull(result.child);
        assertEquals("A", result.child.value);

        assertSame(result.child, CurrentValueCapturingStringDeserializer.lastCurrentValue,
                "Nested property deserializer must see the child bean as currentValue");
    }
}

